BEGIN;


-- Rules
INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '787f6f61-bd7b-5395-a403-b6a14aefcddb'::uuid, '34c4b3f8-a51a-47b1-9bd6-36e7c1301d68'::uuid, 'table', 'Comparative Endings Before a Noun in Every Case', 'Komparativ-Endungen vor dem Nomen in jedem Fall', '{"rows":[["Nominativ maskulin","der größere Tisch","ein größerer Tisch"],["Nominativ feminin","die kleinere Wohnung","eine kleinere Wohnung"],["Nominativ neutrum","das bessere Zimmer","ein besseres Zimmer"],["Akkusativ maskulin","den größeren Tisch","einen größeren Tisch"],["Dativ feminin","der kleineren Wohnung","einer kleineren Wohnung"],["Dativ maskulin","dem größeren Garten","einem größeren Garten"],["Nominativ Plural","die größeren Zimmer","keine größeren Zimmer"]],"headers":["Fall","der/die/das","ein/eine/kein"],"description_de":"Der Komparativ vor einem Nomen bekommt die normale Adjektivendung, genau wie jedes andere Adjektiv.","description_en":"The comparative form before a noun takes the same adjective ending as any other adjective after der/die/das or ein/eine/kein."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'First the comparative -er, then the normal adjective ending: größer + es = größeres.', 'Erst -er, dann die normale Endung: größer + es = größeres.', NULL, NULL, 'The -er of the comparative never replaces the adjective ending — it comes before it: klein + er + e = kleinere.', 'Das -er ersetzt die Adjektivendung nicht, es steht davor: klein + er + e = kleinere.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '787f6f61-bd7b-5395-a403-b6a14aefcddb'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '7c6d5452-5805-59f3-91d4-9aed8918f175'::uuid, '34c4b3f8-a51a-47b1-9bd6-36e7c1301d68'::uuid, 'table', 'Special Comparative Patterns', 'Besondere Komparativ-Muster', '{"rows":[["immer + Komparativ","Es wird immer kälter.","colder and colder"],["viel/etwas + Komparativ","Das Zimmer ist viel ruhiger. / Es ist etwas teurer.","much / a bit + comparative"],["genauso ... wie","Er ist genauso alt wie ich.","just as old as"]],"headers":["Muster","Beispiel","Bedeutung"],"description_de":"immer verstärkt eine Entwicklung, viel/etwas verstärken den Unterschied, genauso ... wie zeigt Gleichheit.","description_en":"immer + comparative shows a growing trend; viel/etwas + comparative shows how much bigger the difference is; genauso ... wie shows two things are equal, not different."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Er ist so alt als ich.","correct":"Er ist so alt wie ich.","explanation_de":"Bei Gleichheit steht wie, nicht als: so alt wie.","explanation_en":"For an equal comparison use wie, not als: so alt wie ich."}]'::jsonb, 'Different amount = als. Same amount = genauso ... wie.', 'Unterschied = als. Gleichheit = genauso ... wie.', NULL, NULL, 'genauso ... wie uses the base adjective, not the comparative: genauso alt wie, never genauso älter wie.', 'genauso ... wie benutzt die Grundform, nicht den Komparativ: genauso alt wie.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '7c6d5452-5805-59f3-91d4-9aed8918f175'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'f82e7609-1efe-5d7a-8acb-df0be5a96046'::uuid, '34c4b3f8-a51a-47b1-9bd6-36e7c1301d68'::uuid, 'common_mistakes', 'Mistakes with the Comparative', 'Fehler beim Komparativ', '{"intro_de":"Diese Fehler passieren oft. Achte auf als/wie und auf die Adjektivendung vor dem Nomen.","intro_en":"These four slips are common at A2. Check als vs wie first, then the ending before a noun.","mistakes":[{"wrong":"Er läuft schneller wie sein Bruder.","correct":"Er läuft schneller als sein Bruder.","explanation_de":"Beim Komparativ steht immer als, nicht wie.","explanation_en":"The comparative always takes als (than), never wie."},{"wrong":"Ich möchte einen besser Job.","correct":"Ich möchte einen besseren Job.","explanation_de":"Vor einem Nomen braucht der Komparativ eine Endung: besseren.","explanation_en":"Before a noun the comparative needs an adjective ending: besseren."},{"wrong":"Das Zimmer ist gutier als meins.","correct":"Das Zimmer ist besser als meins.","explanation_de":"gut ist unregelmäßig: besser, nicht gutier.","explanation_en":"gut is irregular: besser, not gutier."},{"wrong":"Meine Schwester ist junger als ich.","correct":"Meine Schwester ist jünger als ich.","explanation_de":"jung bekommt einen Umlaut: jünger, nicht junger.","explanation_en":"jung takes an umlaut in the comparative: jünger, not junger."}]}'::jsonb, 8, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'als for a difference, the right ending before every noun.', 'als bei Unterschied, die richtige Endung vor jedem Nomen.', NULL, NULL, 'Almost every comparative mistake is either als/wie confusion or a missing ending before a noun.', 'Fast jeder Komparativ-Fehler ist als/wie oder eine fehlende Endung vor dem Nomen.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'f82e7609-1efe-5d7a-8acb-df0be5a96046'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'ee269eb5-0d9e-5891-9f6d-a3c73f62d8be'::uuid, 'd0f70c42-4a0b-44ed-9279-837e0dc5bc67'::uuid, 'explanation_patterns', 'Two-Part Connectors: entweder ... oder and nicht ... sondern', 'Zweiteilige Konnektoren: entweder ... oder und nicht ... sondern', '{"intro_de":"entweder kann vorn allein stehen (Verb direkt danach) oder vor dem Subjekt. Beides ist richtig.","intro_en":"entweder can stand alone (verb follows directly) or before the subject. Both are correct.","situations":[{"name":"entweder allein (Inversion)","example_de":"Entweder gehen wir ins Kino, oder wir bleiben zu Hause.","example_en":"Either we go to the cinema, or we stay home.","description":"entweder alone, verb comes right after it","explanation":"Hier steht entweder allein, darum kommt das Verb direkt danach."},{"name":"entweder + Subjekt (keine Inversion)","example_de":"Entweder du entschuldigst dich, oder ich gehe.","example_en":"Either you apologize, or I leave.","description":"entweder before the subject, normal order","explanation":"Hier steht das Subjekt direkt nach entweder, das Verb bleibt an Position 2."},{"name":"nicht ... sondern","example_de":"Er ist nicht zu Hause, sondern noch im Büro.","example_en":"He is not at home, but rather still at the office.","description":"a correction after nicht","explanation":"sondern korrigiert die Aussage nach nicht."}],"key_insight_de":"Beide entweder-Formen sind richtig. nicht ... sondern ändert die Wortstellung nie.","key_insight_en":"Both entweder forms are correct. nicht ... sondern never changes word order."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'entweder always needs its partner oder later in the sentence.', 'entweder braucht immer sein Partnerwort oder.', NULL, NULL, 'Comma before oder here is optional, exactly as with plain oder.', 'Das Komma vor oder ist hier optional, genau wie bei einfachem oder.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'ee269eb5-0d9e-5891-9f6d-a3c73f62d8be'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '5b1507e3-2de1-5519-83b9-e0e86cd6b632'::uuid, 'd0f70c42-4a0b-44ed-9279-837e0dc5bc67'::uuid, 'explanation_exceptions', 'Joining Verbs Without Repeating the Subject', 'Zwei Verben, ein Subjekt', '{"intro_de":"Wenn zwei Verben dasselbe Subjekt haben, kannst du das Subjekt einmal weglassen.","intro_en":"When two verbs share the same subject, you can drop the subject the second time.","situations":[{"name":"Ein Subjekt, zwei Verben","example_de":"Ich koche und räume auf.","example_en":"I cook and tidy up.","description":"no comma, no repeated subject","explanation":"Kein Komma, weil kein zweites Subjekt kommt."},{"name":"Zwei Subjekte, zwei Sätze","example_de":"Ich koche, und du räumst auf.","example_en":"I cook, and you tidy up.","description":"comma optional, subject repeated","explanation":"Hier stehen zwei volle Sätze, das Komma ist optional."}],"key_insight_de":"Ohne wiederholtes Subjekt: kein Komma. Mit zwei vollen Sätzen ist das Komma vor und/oder optional.","key_insight_en":"No repeated subject → no comma. Two full clauses → the comma becomes optional."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Same subject once, no comma before und.', 'Ein Subjekt, kein Komma vor und.', NULL, NULL, 'This is not a full second sentence, so it behaves differently from denn/aber/sondern.', 'Das ist kein zweiter vollständiger Satz, anders als bei denn/aber/sondern.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '5b1507e3-2de1-5519-83b9-e0e86cd6b632'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '1c2ea99b-1000-5e1b-9538-243e972f3260'::uuid, 'd0f70c42-4a0b-44ed-9279-837e0dc5bc67'::uuid, 'common_mistakes', 'Mistakes with Two-Part Connectors and Commas', 'Fehler mit zweiteiligen Konnektoren und Kommas', '{"intro_de":"Diese Fehler passieren oft mit aber, dem Komma und entweder ... oder.","intro_en":"These mistakes are common with aber, the comma and entweder ... oder.","mistakes":[{"wrong":"Der Film ist lang aber er ist interessant.","correct":"Der Film ist lang, aber er ist interessant.","explanation_de":"Vor aber steht immer ein Komma, wenn zwei Sätze verbunden werden.","explanation_en":"A comma always comes before aber when it joins two clauses."},{"wrong":"Ich koche, und räume auf.","correct":"Ich koche und räume auf.","explanation_de":"Kein zweites Subjekt, darum kein Komma vor und.","explanation_en":"No second subject, so no comma before und."},{"wrong":"Oder wir gehen ins Kino, oder wir bleiben hier.","correct":"Entweder wir gehen ins Kino, oder wir bleiben hier.","explanation_de":"Der erste Teil heißt entweder, nicht oder.","explanation_en":"The first part of the pair is entweder, not oder."}]}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'aber/denn/sondern between two clauses always want a comma.', 'aber/denn/sondern zwischen zwei Sätzen wollen immer ein Komma.', NULL, NULL, 'Check first: is there a second subject? That decides the comma.', 'Erst prüfen: gibt es ein zweites Subjekt? Das entscheidet über das Komma.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '1c2ea99b-1000-5e1b-9538-243e972f3260'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '61535b4a-df30-5deb-b939-019602318c95'::uuid, '0d1d11e3-7551-4f74-9036-df5fab56f320'::uuid, 'table', 'Future Tense in Subordinate Clauses', 'Futur I im Nebensatz', '{"rows":[["dass","Ich denke, dass sie pünktlich ankommen wird.","infinitive + wird at the end"],["weil","Ich nehme einen Schirm, weil es regnen wird.","infinitive + wird at the end"],["ob","Ich frage mich, ob er rechtzeitig kommen wird.","infinitive + wird at the end"]],"headers":["Konjunktion","Beispiel","Muster"],"description_de":"Im Nebensatz steht die ganze Verbgruppe am Ende: erst der Infinitiv, dann werden. Achtung: Im wenn-Satz steht Präsens, nie Futur.","description_en":"In a subordinate clause the whole verb group goes to the end: the infinitive first, then the conjugated form of werden. Note that a real wenn-clause about the future normally takes Präsens instead (Wenn du Zeit hast, ruf mich an.) — see the topic''s own Present Tense for Future rule."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'werden acts like a modal verb: infinitive, then werden, both at the very end.', 'werden verhält sich wie ein Modalverb: Infinitiv, dann werden, beide ganz am Ende.', NULL, NULL, 'werden never stays in position 2 inside a subordinate clause — it moves to the very end, after the infinitive.', 'werden bleibt im Nebensatz nicht auf Position 2 — es steht ganz am Ende.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '61535b4a-df30-5deb-b939-019602318c95'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'ba230b8c-ec62-58c1-bc9c-f69f1dea406f'::uuid, '0d1d11e3-7551-4f74-9036-df5fab56f320'::uuid, 'tip', 'Futur I or Präsens? What the Exam Expects', 'Futur I oder Präsens? Was die Prüfung erwartet', '{"text_de":"In der Schreibprüfung (Teil 2) reicht meist Präsens + Zeitwort. Für ein festes Versprechen oder eine formelle Ankündigung ist Futur I besser.","text_en":"In the writing exam (Teil 2), present tense + time word is usually enough for everyday plans. Use Futur I when you make a firm promise or a formal announcement — it sounds more certain and more official.","example_de":"Alltag: Ich komme am Montag. Versprechen: Ich werde bestimmt kommen.","example_en":"Everyday plan: Ich komme am Montag. (I''m coming Monday.) Promise: Ich werde bestimmt kommen. (I will definitely come.)"}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Writing Teil 2: present tense is enough. Formal letter: Futur I.', 'Schreiben Teil 2: Präsens reicht. Formeller Brief: Futur I.', 'In a formal letter or e-mail (Schreiben Teil 2), Futur I signals a firm commitment: Ich werde Ihnen die Unterlagen schicken.', 'In einem formellen Brief zeigt Futur I ein festes Versprechen: Ich werde Ihnen die Unterlagen schicken.', NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'ba230b8c-ec62-58c1-bc9c-f69f1dea406f'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'ae3bbb1f-51ee-5de9-bd20-9368422de91c'::uuid, '0d1d11e3-7551-4f74-9036-df5fab56f320'::uuid, 'common_mistakes', 'Mistakes with Futur I', 'Fehler mit Futur I', '{"intro_de":"Diese vier Fehler kommen oft vor. Achte auf die Form von werden und wo der Infinitiv steht.","intro_en":"These four slips are common at A2. Check the form of werden first, then where the infinitive stands.","mistakes":[{"wrong":"Ich werde nächste Woche arbeite.","correct":"Ich werde nächste Woche arbeiten.","explanation_de":"Nach werden steht immer der Infinitiv: arbeiten, nicht arbeite.","explanation_en":"werden is always followed by the infinitive: arbeiten, not arbeite."},{"wrong":"Wir werden morgen zu Hause.","correct":"Wir werden morgen zu Hause sein.","explanation_de":"Nach werden fehlt hier der Infinitiv: sein muss stehen.","explanation_en":"The infinitive is missing after werden: sein needs to be there."},{"wrong":"Ich hoffe, dass sie wird pünktlich sein.","correct":"Ich hoffe, dass sie pünktlich sein wird.","explanation_de":"Im dass-Satz steht werden ganz am Ende, nicht in der Mitte.","explanation_en":"In a dass-clause, werden goes to the very end, not the middle."},{"wrong":"Sie wird das erklären morgen.","correct":"Sie wird das morgen erklären.","explanation_de":"Der Infinitiv erklären steht ganz am Ende; morgen kommt davor.","explanation_en":"The infinitive erklären stands at the very end; time words like morgen come before it."}]}'::jsonb, 8, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'werden: position 2 in a main clause, the very end in a subordinate clause. Infinitive always right before it.', 'werden: Position 2 im Hauptsatz, ganz am Ende im Nebensatz. Infinitiv immer davor.', NULL, NULL, 'werden behaves like a modal verb: position 2 in a main clause, the very end in a subordinate clause. The infinitive always stands right before it.', 'werden verhält sich wie ein Modalverb: Position 2 im Hauptsatz, ganz am Ende im Nebensatz. Der Infinitiv steht immer davor.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'ae3bbb1f-51ee-5de9-bd20-9368422de91c'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '3ddead17-0ed6-51d0-b931-83817f8bc6ef'::uuid, '7e275945-433d-4e15-a87b-e33943d9fc80'::uuid, 'table', 'More Reflexive Verbs: With or Without a Body Part', 'Weitere reflexive Verben: mit oder ohne Körperteil', '{"headers":["Verb","Beispiel","Erklärung"],"rows":[["sich kämmen (kein Objekt)","Ich kämme mich.","Akkusativ: mich"],["sich kämmen (mit Objekt)","Ich kämme mir die Haare.","Dativ: mir + Akkusativobjekt"],["sich anziehen (kein Objekt)","Ich ziehe mich an.","Akkusativ: mich"],["sich anziehen (mit Objekt)","Ich ziehe mir die Jacke an.","Dativ: mir + Akkusativobjekt"],["sich putzen (mit Objekt)","Ich putze mir die Zähne.","Dativ: mir + Akkusativobjekt"]],"description_de":"Ohne Objekt steht der Akkusativ: mich. Mit einem Objekt wie die Haare steht der Dativ: mir.","description_en":"Without an object, use the accusative: mich. With an object like die Haare, use the dative: mir."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Object present? Then dative: mir, dir, sich.', 'Objekt dabei? Dann Dativ: mir, dir, sich.', NULL, NULL, 'First look for an object, then choose the case.', 'Erst das Objekt suchen, dann den Fall wählen.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '3ddead17-0ed6-51d0-b931-83817f8bc6ef'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '764c1bec-5e09-5f58-b7f8-cab85f8fe4fa'::uuid, '7e275945-433d-4e15-a87b-e33943d9fc80'::uuid, 'explanation_patterns', 'Reflexive Verbs in Perfekt and with Modal Verbs', 'Reflexive Verben im Perfekt und mit Modalverben', '{"intro_de":"Das Reflexivpronomen steht direkt nach dem konjugierten Verb. In Fragen steht es nach dem Subjekt.","intro_en":"The reflexive pronoun comes right after the conjugated verb. In questions, it comes after the subject.","situations":[{"name":"Perfekt: Pronomen nach haben","example_de":"Ich habe mich für den Kurs angemeldet.","example_en":"I signed up for the course.","description":"pronoun position in Perfekt","explanation":"mich steht direkt nach habe, das Partizip kommt ans Ende."},{"name":"Modalverb: Pronomen nach dem Modalverb","example_de":"Er muss sich beeilen.","example_en":"He has to hurry.","description":"pronoun position with a modal verb","explanation":"sich steht direkt nach muss, der Infinitiv kommt ans Ende."},{"name":"Frage im Perfekt","example_de":"Hast du dich schon angemeldet?","example_en":"Have you already signed up?","description":"question word order","explanation":"dich steht direkt nach dem Subjekt du."}],"key_insight_de":"Das Pronomen bleibt vorn, das Partizip oder der Infinitiv geht ans Ende.","key_insight_en":"The pronoun stays near the front; the participle or infinitive goes to the end."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Pronoun first, main verb form last.', 'Erst das Pronomen, dann am Ende die Verbform.', NULL, NULL, 'habe/muss + reflexive pronoun + ... + participle/infinitive at the end.', 'habe/muss + Pronomen + ... + Partizip/Infinitiv am Ende.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '764c1bec-5e09-5f58-b7f8-cab85f8fe4fa'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '913ece91-dab9-5002-8368-ac221e7f89a2'::uuid, '7e275945-433d-4e15-a87b-e33943d9fc80'::uuid, 'common_mistakes', 'Mistakes with Reflexive Verbs in Perfekt and with Modals', 'Fehler bei reflexiven Verben im Perfekt und mit Modalverben', '{"intro_de":"Diese Fehler passieren oft im Perfekt und mit Modalverben.","intro_en":"These mistakes are common in Perfekt and with modal verbs.","mistakes":[{"wrong":"Ich habe angemeldet mich für den Kurs.","correct":"Ich habe mich für den Kurs angemeldet.","explanation_de":"mich steht direkt nach habe, nicht am Ende.","explanation_en":"mich comes right after habe, not at the end."},{"wrong":"Sie muss beeilen sich, der Film beginnt gleich.","correct":"Sie muss sich beeilen, der Film beginnt gleich.","explanation_de":"sich steht direkt nach dem Modalverb muss.","explanation_en":"sich comes right after the modal verb muss."},{"wrong":"Er zieht sich an die Jacke.","correct":"Er zieht sich die Jacke an.","explanation_de":"an ist trennbar und geht ans Satzende.","explanation_en":"an is separable and goes to the end of the sentence."}]}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Say the pronoun early, send the rest of the verb to the end.', 'Pronomen früh, Verbrest ans Ende.', NULL, NULL, 'Most reflexive mistakes are word-order mistakes, not pronoun mistakes.', 'Die meisten Fehler sind Wortstellungsfehler, keine Pronomenfehler.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '913ece91-dab9-5002-8368-ac221e7f89a2'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '39bf0a4a-2970-57e6-8a69-4fa8781debcc'::uuid, '71b4f297-92c2-47e9-b5f1-feb784b30226'::uuid, 'explanation_patterns', 'war and hatte in weil/dass/wenn Clauses', 'war und hatte in weil-/dass-/wenn-Sätzen', '{"intro_de":"In einem Nebensatz gehen war und hatte ans Ende, wie jedes Verb.","intro_en":"In a subordinate clause, war and hatte go to the end, just like any verb.","situations":[{"name":"weil + war","example_de":"Ich bin zu Hause geblieben, weil ich krank war.","example_en":"I stayed home because I was sick.","description":"weil clause with war","explanation":"Im weil-Satz steht war ganz am Ende."},{"name":"dass + hatte","example_de":"Sie hat gesagt, dass sie keine Zeit hatte.","example_en":"She said that she had no time.","description":"dass clause with hatte","explanation":"Im dass-Satz steht hatte ganz am Ende."},{"name":"wenn + war (wiederholt)","example_de":"Wenn das Wetter schlecht war, sind wir zu Hause geblieben.","example_en":"Whenever the weather was bad, we stayed home.","description":"wenn clause first, repeated past situations","explanation":"Im wenn-Satz steht war am Ende; es geht um wiederholte Situationen, nicht um ein einziges Mal."}],"key_insight_de":"war/hatte sind ganz normale Verben: im Nebensatz gehen sie ans Ende.","key_insight_en":"war/hatte are ordinary verbs: in a subordinate clause they go to the end too."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Nebensatz rule applies to war/hatte too: verb to the end.', 'Die Nebensatzregel gilt auch für war/hatte: Verb ans Ende.', NULL, NULL, 'weil/dass/wenn always send war and hatte to the end of their clause.', 'weil/dass/wenn schicken war und hatte immer ans Satzende.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '39bf0a4a-2970-57e6-8a69-4fa8781debcc'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '6865ec4c-24b4-5fe8-b04f-fff794fb85d0'::uuid, '71b4f297-92c2-47e9-b5f1-feb784b30226'::uuid, 'table', 'es gab, es war + Weather and Time (Storytelling)', 'es gab, es war + Wetter und Zeit (Erzählen)', '{"headers":["Ausdruck","Bedeutung","Beispiel"],"rows":[["es gab","there was / there were","Es gab viele Leute auf der Party."],["es war + Wetter","it was + weather","Es war sehr kalt."],["es war + Zeit","it was + time","Es war schon spät."],["es gab kein(e) ...","there was no ...","Es gab kein Brot mehr."]],"description_de":"Diese Ausdrücke brauchst du oft, wenn du im Sprechen Teil 2 eine Geschichte erzählst.","description_en":"You need these often when you tell a story in Sprechen Teil 2."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'es gab and es war never change for plural: always gab, always war.', 'es gab und es war ändern sich nie im Plural.', NULL, NULL, 'es gab and es war always stay singular, unlike es gibt in the present.', 'es gab und es war stehen immer im Singular.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '6865ec4c-24b4-5fe8-b04f-fff794fb85d0'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'e056934e-2d6b-5e6e-bbee-dc81084fb502'::uuid, '71b4f297-92c2-47e9-b5f1-feb784b30226'::uuid, 'common_mistakes', 'Mistakes with war, hatte and es gab', 'Fehler mit war, hatte und es gab', '{"intro_de":"Diese Fehler passieren oft bei Nebensätzen und bei es gab.","intro_en":"These mistakes are common in subordinate clauses and with es gab.","mistakes":[{"wrong":"Weil ich bin krank war, bin ich zu Hause geblieben.","correct":"Weil ich krank war, bin ich zu Hause geblieben.","explanation_de":"Im weil-Satz steht nur ein Verb am Ende: war.","explanation_en":"The weil clause has only one verb, and it goes at the end: war."},{"wrong":"Es waren sehr kalt im Winter.","correct":"Es war sehr kalt im Winter.","explanation_de":"es war ist immer Singular, nie waren.","explanation_en":"es war is always singular; never waren."},{"wrong":"Es gaben keine Milch mehr.","correct":"Es gab keine Milch mehr.","explanation_de":"es gab ändert sich nie, auch nicht im Plural.","explanation_en":"es gab never changes, not even for plural."}]}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'es war and es gab: always singular, always fixed.', 'es war und es gab: immer Singular, immer fest.', NULL, NULL, 'Confusing es war/es gab with plural agreement is the most common error here.', 'Der häufigste Fehler: es war/es gab fälschlich in den Plural setzen.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'e056934e-2d6b-5e6e-bbee-dc81084fb502'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '0244ca21-23f1-5b27-abbc-95a9fdf7ee51'::uuid, 'b11f911b-9c17-4100-b0a7-4a6c905773a4'::uuid, 'table', 'Superlative Endings in Every Case', 'Superlativ-Endungen in jedem Fall', '{"rows":[["Nominativ maskulin","der beste Film"],["Nominativ feminin","die schönste Stadt"],["Akkusativ maskulin","den besten Film"],["Akkusativ neutrum","das schönste Fahrrad"],["Dativ maskulin/neutrum","dem besten Film"],["Nominativ Plural","die meisten Leute"],["Akkusativ Plural","die meisten Leute"]],"headers":["Fall","Beispiel"],"description_de":"Vor einem Nomen bekommt der Superlativ die normale Adjektivendung, genau wie jedes andere Adjektiv nach der/die/das.","description_en":"Before a noun the superlative takes the normal adjective ending — the same ending any adjective would take after der/die/das in that case."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'der/die/das + superlative + normal ending, in any case.', 'der/die/das + Superlativ + normale Endung, in jedem Fall.', NULL, NULL, 'The -ste/-este never changes; only the ending after it changes with the case: der beste, den besten, dem besten.', '-ste/-este ändert sich nicht; nur die Endung danach ändert sich mit dem Fall.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '0244ca21-23f1-5b27-abbc-95a9fdf7ee51'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '311cb981-2f25-5c3d-ab8d-872c2d67dbe9'::uuid, 'b11f911b-9c17-4100-b0a7-4a6c905773a4'::uuid, 'dialogue', 'Speaking Exam: Talking about Favorites', 'Sprechen-Prüfung: Über Vorlieben sprechen', '{"lines":[{"de":"Was machst du am liebsten in deiner Freizeit?","en":"What do you like doing most in your free time?","speaker":"Lukas","highlight":"am liebsten"},{"de":"Ich lese am liebsten, aber ich koche auch gern.","en":"I like reading most, but I also enjoy cooking.","speaker":"Sara","highlight":"Ich lese am liebsten"},{"de":"Und was gefällt dir am besten an deiner Stadt?","en":"And what do you like best about your city?","speaker":"Lukas","highlight":"am besten"},{"de":"Am besten gefällt mir der Park am Fluss.","en":"What I like best is the park by the river.","speaker":"Sara","highlight":"Am besten gefällt mir"},{"de":"Gehen dort nicht die meisten Leute am Wochenende spazieren?","en":"Don''t most people go for a walk there on the weekend?","speaker":"Lukas","highlight":"die meisten Leute"}],"context_de":"Sprechen Teil 2: Dein Partner fragt nach deinen Vorlieben.","context_en":"Speaking Part 2: your partner asks about your preferences and favorites."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'am liebsten / am besten answer ''what do you like most'' without needing a noun.', 'am liebsten / am besten beantworten ''was magst du am meisten'' ohne Nomen.', NULL, NULL, 'In the speaking exam, am liebsten/am besten/am meisten work as adverbs — no article, no ending.', 'In der Sprechprüfung sind am liebsten/am besten/am meisten Adverbien — kein Artikel, keine Endung.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '311cb981-2f25-5c3d-ab8d-872c2d67dbe9'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'e1417811-ccda-5f70-bb32-61d3fa94be57'::uuid, 'b11f911b-9c17-4100-b0a7-4a6c905773a4'::uuid, 'common_mistakes', 'Mistakes with the Superlative', 'Fehler beim Superlativ', '{"intro_de":"Diese vier Fehler kommen oft vor. Achte auf am + sten, die Endung und die unregelmäßigen Formen.","intro_en":"These four slips are common at A2. Watch am + sten, the final -n, and the irregular forms.","mistakes":[{"wrong":"Sie ist am besten Fahrerin.","correct":"Sie ist die beste Fahrerin.","explanation_de":"Vor einem Nomen steht der/die/das + Superlativ, nicht am.","explanation_en":"Before a noun, use der/die/das + superlative, not am."},{"wrong":"Das ist das gutste Restaurant.","correct":"Das ist das beste Restaurant.","explanation_de":"gut ist unregelmäßig: beste, nicht gutste.","explanation_en":"gut is irregular: beste, not gutste."},{"wrong":"Er singt am schönste von allen.","correct":"Er singt am schönsten von allen.","explanation_de":"am + sten braucht immer das -n am Ende: am schönsten.","explanation_en":"am + sten always needs the final -n: am schönsten."},{"wrong":"Das war der kalteste Morgen.","correct":"Das war der kälteste Morgen.","explanation_de":"kalt bekommt einen Umlaut: kälteste, nicht kalteste.","explanation_en":"kalt takes an umlaut: kälteste, not kalteste."}]}'::jsonb, 8, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Noun nearby? Use der/die/das. No noun? Use am + sten.', 'Nomen in der Nähe? der/die/das. Kein Nomen? am + sten.', NULL, NULL, 'am + sten always ends in -n, and the irregulars (gut, viel, gern, hoch, nah) never just add -ste to the base word.', 'am + sten endet immer auf -n, und die Unregelmäßigen bekommen nie einfach -ste.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'e1417811-ccda-5f70-bb32-61d3fa94be57'::uuid);

-- Examples
INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '19c490cf-4129-55dd-b8a0-e81758a099cf'::uuid, '34c4b3f8-a51a-47b1-9bd6-36e7c1301d68'::uuid, 'Wir ziehen in eine ruhigere Wohnung.', 'We are moving into a quieter apartment.', 'ruhigere', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wohnung is feminine accusative after in (motion into), so the comparative takes -e: ruhigere.', 'Wohnung ist feminin Akkusativ nach in (Richtung): ruhigere.', '{"Wir":"We","ziehen":"are moving","in eine ruhigere":"into a quieter","Wohnung":"apartment"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '19c490cf-4129-55dd-b8a0-e81758a099cf'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '0156eba8-5542-58c1-aa64-2815f06ecc36'::uuid, '34c4b3f8-a51a-47b1-9bd6-36e7c1301d68'::uuid, 'Die neue Wohnung ist genauso teuer wie die alte.', 'The new apartment is just as expensive as the old one.', 'genauso teuer wie', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'genauso ... wie shows equality: both apartments cost the same.', 'genauso ... wie zeigt Gleichheit: beide Wohnungen kosten dasselbe.', '{"Die neue Wohnung":"The new apartment","ist":"is","genauso teuer wie":"just as expensive as","die alte":"the old one"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '0156eba8-5542-58c1-aa64-2815f06ecc36'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '440a5471-6bca-535c-a6b5-dbc4c1be3c5d'::uuid, '34c4b3f8-a51a-47b1-9bd6-36e7c1301d68'::uuid, 'Das Wetter wird im Herbst immer kälter.', 'The weather gets colder and colder in autumn.', 'immer kälter', NULL, 11, '2026-09-05T12:00:00+00:00'::timestamptz, 'immer + comparative describes a continuing change: colder and colder.', 'immer + Komparativ zeigt eine Entwicklung: immer kälter.', '{"Das Wetter":"The weather","wird":"gets, becomes","im Herbst":"in autumn","immer kälter":"colder and colder"}'::jsonb, 3, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '440a5471-6bca-535c-a6b5-dbc4c1be3c5d'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'deaedd1f-6bf0-5bc1-846a-62963e73291f'::uuid, '34c4b3f8-a51a-47b1-9bd6-36e7c1301d68'::uuid, 'Mein neuer Chef ist etwas älter als ich.', 'My new boss is a bit older than me.', 'etwas älter', NULL, 12, '2026-09-05T12:00:00+00:00'::timestamptz, 'etwas + comparative softens the difference: a bit older, not much older.', 'etwas + Komparativ zeigt einen kleinen Unterschied: etwas älter.', '{"Mein neuer Chef":"My new boss","ist":"is","etwas älter":"a bit older","als":"than","ich":"me"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'deaedd1f-6bf0-5bc1-846a-62963e73291f'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '415c010d-947c-5930-81ef-67598f8ad0c5'::uuid, 'd0f70c42-4a0b-44ed-9279-837e0dc5bc67'::uuid, 'Entweder gehen wir ins Kino, oder wir bleiben zu Hause.', 'Either we go to the cinema, or we stay home.', 'Entweder', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'entweder opens the choice, oder introduces the second option.', 'entweder eröffnet die Wahl, oder bringt die zweite Möglichkeit.', '{"Entweder":"either","gehen":"go","wir":"we","ins":"into the (acc.)","Kino":"cinema","oder":"or","bleiben":"stay","zu":"at","Hause":"home"}'::jsonb, 2, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '415c010d-947c-5930-81ef-67598f8ad0c5'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '4f2d30f0-e210-5a27-9105-940c8e3b798a'::uuid, 'd0f70c42-4a0b-44ed-9279-837e0dc5bc67'::uuid, 'Ich putze die Wohnung und koche das Abendessen.', 'I clean the apartment and cook dinner.', 'putze die Wohnung und koche', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'One subject, two verbs joined by und: no comma is needed.', 'Ein Subjekt, zwei Verben mit und: kein Komma nötig.', '{"Ich":"I","putze":"clean","die":"the (acc. fem.)","Wohnung":"apartment","und":"and","koche":"cook","das":"the (acc. neut.)","Abendessen":"dinner"}'::jsonb, 2, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '4f2d30f0-e210-5a27-9105-940c8e3b798a'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '547343d3-f4f6-54c3-9218-b6af2a3dd19b'::uuid, 'd0f70c42-4a0b-44ed-9279-837e0dc5bc67'::uuid, 'Er ist nicht zu Hause, sondern noch im Büro.', 'He is not at home, but rather still at the office.', 'sondern', NULL, 11, '2026-09-05T12:00:00+00:00'::timestamptz, 'sondern corrects the negative statement nicht zu Hause.', 'sondern korrigiert die negative Aussage nicht zu Hause.', '{"Er":"he","ist":"is","nicht":"not","zu":"at","Hause":"home","sondern":"but rather","noch":"still","im":"in the (dat.)","Büro":"office"}'::jsonb, 2, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '547343d3-f4f6-54c3-9218-b6af2a3dd19b'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '7971708b-823c-5492-b6b6-1750196d6556'::uuid, 'd0f70c42-4a0b-44ed-9279-837e0dc5bc67'::uuid, 'Entweder du entschuldigst dich, oder ich gehe.', 'Either you apologize, or I leave.', 'Entweder du entschuldigst dich', NULL, 12, '2026-09-05T12:00:00+00:00'::timestamptz, 'Two full clauses, two subjects: the comma before oder is optional.', 'Zwei volle Sätze, zwei Subjekte: das Komma vor oder ist optional.', '{"Entweder":"either","du":"you","entschuldigst":"apologize","dich":"yourself (reflexive)","oder":"or","ich":"I","gehe":"go/leave"}'::jsonb, 3, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '7971708b-823c-5492-b6b6-1750196d6556'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '20d1cca6-5ea7-5076-8fd3-1f2c98fe64ec'::uuid, '0d1d11e3-7551-4f74-9036-df5fab56f320'::uuid, 'Er hofft, dass er die Prüfung bestehen wird.', 'He hopes that he will pass the exam.', 'bestehen wird', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'Future tense in a dass-clause: infinitive (bestehen) then werden at the very end.', 'Futur im dass-Satz: Infinitiv (bestehen), dann werden ganz am Ende.', '{"Er":"He","hofft":"hopes","dass er":"that he","die Prüfung":"the exam","bestehen wird":"will pass"}'::jsonb, 3, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '20d1cca6-5ea7-5076-8fd3-1f2c98fe64ec'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'a395058d-60a0-5575-9db9-ee46d1fe5b92'::uuid, '0d1d11e3-7551-4f74-9036-df5fab56f320'::uuid, 'Wir werden im Urlaub viel schwimmen.', 'We will swim a lot on vacation.', 'werden im Urlaub viel schwimmen', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'werden in position 2, the infinitive schwimmen at the end.', 'werden auf Position 2, der Infinitiv schwimmen am Ende.', '{"Wir":"We","werden":"will","im Urlaub":"on vacation","viel":"a lot","schwimmen":"swim"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'a395058d-60a0-5575-9db9-ee46d1fe5b92'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '55b07983-3ca9-5813-a7c0-b8a71eb45067'::uuid, '0d1d11e3-7551-4f74-9036-df5fab56f320'::uuid, 'Ich verspreche, dass ich pünktlich sein werde.', 'I promise that I will be on time.', 'sein werde', NULL, 11, '2026-09-05T12:00:00+00:00'::timestamptz, 'A promise in a dass-clause: infinitive (sein) then werde at the very end.', 'Ein Versprechen im dass-Satz: Infinitiv (sein), dann werde ganz am Ende.', '{"Ich":"I","verspreche":"promise","dass ich":"that I","pünktlich":"on time","sein werde":"will be"}'::jsonb, 3, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '55b07983-3ca9-5813-a7c0-b8a71eb45067'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'df1f9937-3a32-5a24-bb27-773fbdb0e63e'::uuid, '0d1d11e3-7551-4f74-9036-df5fab56f320'::uuid, 'Nächste Woche werden wir das neue Büro eröffnen.', 'Next week we will open the new office.', 'werden wir das neue Büro eröffnen', NULL, 12, '2026-09-05T12:00:00+00:00'::timestamptz, 'Time-first sentence: nächste Woche in position 1, werden still in position 2.', 'Zeit zuerst: nächste Woche auf Position 1, werden bleibt auf Position 2.', '{"Nächste Woche":"Next week","werden wir":"we will","das neue Büro":"the new office","eröffnen":"open"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'df1f9937-3a32-5a24-bb27-773fbdb0e63e'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '27b08392-1f80-506a-b19c-3590471e187a'::uuid, '7e275945-433d-4e15-a87b-e33943d9fc80'::uuid, 'Ich habe mich für den Deutschkurs angemeldet.', 'I signed up for the German course.', 'habe mich', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'mich follows habe immediately; the participle angemeldet goes to the end.', 'mich steht direkt nach habe, angemeldet steht am Ende.', '{"Ich":"I","habe":"have","mich":"myself (reflexive, acc.)","für":"for","den":"the (acc. masc.)","Deutschkurs":"German course","angemeldet":"signed up (past participle)"}'::jsonb, 2, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '27b08392-1f80-506a-b19c-3590471e187a'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '26daa6b8-5a25-52d7-8624-9f7d1801a53a'::uuid, '7e275945-433d-4e15-a87b-e33943d9fc80'::uuid, 'Er muss sich beeilen, weil der Bus bald kommt.', 'He has to hurry because the bus is coming soon.', 'muss sich beeilen', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'sich comes right after the modal muss; beeilen stays an infinitive at the end.', 'sich steht direkt nach muss, beeilen bleibt Infinitiv am Ende.', '{"Er":"he","muss":"has to (modal)","sich":"himself (reflexive)","beeilen":"to hurry","weil":"because","der":"the (nom. masc.)","Bus":"bus","bald":"soon","kommt":"comes"}'::jsonb, 2, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '26daa6b8-5a25-52d7-8624-9f7d1801a53a'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'e9908871-4294-5dd6-8cac-6641e5c7f15f'::uuid, '7e275945-433d-4e15-a87b-e33943d9fc80'::uuid, 'Ich kämme mir die Haare vor dem Spiegel.', 'I comb my hair in front of the mirror.', 'kämme mir', NULL, 11, '2026-09-05T12:00:00+00:00'::timestamptz, 'die Haare is the direct object, so the reflexive pronoun is dative: mir.', 'die Haare ist das Akkusativobjekt, darum steht der Dativ: mir.', '{"Ich":"I","kämme":"comb","mir":"myself (reflexive, dat.)","die":"the (acc. pl.)","Haare":"hair","vor":"in front of","dem":"the (dat. masc./neut.)","Spiegel":"mirror"}'::jsonb, 2, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'e9908871-4294-5dd6-8cac-6641e5c7f15f'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '4f97bb31-abc7-579a-b8d3-33b425eebba7'::uuid, '7e275945-433d-4e15-a87b-e33943d9fc80'::uuid, 'Habt ihr euch schon für den Kurs angemeldet?', 'Have you all already signed up for the course?', 'euch', NULL, 12, '2026-09-05T12:00:00+00:00'::timestamptz, 'ihr takes euch, which is identical for accusative and dative.', 'ihr → euch. Diese Form ist im Akkusativ und im Dativ gleich.', '{"Habt":"have (2nd pl.)","ihr":"you all","euch":"yourselves (reflexive)","schon":"already","für":"for","den":"the (acc. masc.)","Kurs":"course","angemeldet":"signed up (past participle)"}'::jsonb, 3, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '4f97bb31-abc7-579a-b8d3-33b425eebba7'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'ca4aaf45-4374-59cc-96ab-efd91419564f'::uuid, '71b4f297-92c2-47e9-b5f1-feb784b30226'::uuid, 'Es gab viele Leute auf der Party.', 'There were a lot of people at the party.', 'Es gab', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'es gab is a fixed impersonal chunk meaning there was/were.', 'es gab ist ein fester Ausdruck.', '{"Es":"it (impersonal)","gab":"was/were given, there was","viele":"many","Leute":"people","auf":"at","der":"the (dat. fem.)","Party":"party"}'::jsonb, 1, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'ca4aaf45-4374-59cc-96ab-efd91419564f'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'a67a674f-2278-5caf-ad30-d7dbb617ac09'::uuid, '71b4f297-92c2-47e9-b5f1-feb784b30226'::uuid, 'Es war schon spät, aber wir waren noch wach.', 'It was already late, but we were still awake.', 'Es war', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'es war + time expression is a common way to set the scene.', 'es war + Zeitangabe beschreibt oft die Situation am Anfang.', '{"Es":"it (impersonal)","war":"was","schon":"already","spät":"late","aber":"but","wir":"we","waren":"were","noch":"still","wach":"awake"}'::jsonb, 2, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'a67a674f-2278-5caf-ad30-d7dbb617ac09'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '9d8c8ae8-dbdc-5dc4-b9ec-ef1547b96384'::uuid, '71b4f297-92c2-47e9-b5f1-feb784b30226'::uuid, 'Ich war traurig, denn es gab keinen Kuchen mehr.', 'I was sad because there was no more cake.', 'es gab', NULL, 11, '2026-09-05T12:00:00+00:00'::timestamptz, 'denn keeps normal word order, so es gab stays together.', 'denn ändert die Wortstellung nicht, darum bleibt es gab zusammen.', '{"Ich":"I","war":"was","traurig":"sad","denn":"because/for","es":"it (impersonal)","gab":"was given, there was","keinen":"no (acc. masc.)","Kuchen":"cake","mehr":"anymore"}'::jsonb, 2, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '9d8c8ae8-dbdc-5dc4-b9ec-ef1547b96384'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'd3b7301f-e10a-57cd-97a3-04f557c257e6'::uuid, '71b4f297-92c2-47e9-b5f1-feb784b30226'::uuid, 'Sie hat gesagt, dass sie keine Zeit hatte.', 'She said that she had no time.', 'hatte', NULL, 12, '2026-09-05T12:00:00+00:00'::timestamptz, 'hatte goes to the end of the dass clause.', 'Im dass-Satz steht hatte am Ende.', '{"Sie":"she (sentence-initial)","hat":"has","gesagt":"said (past participle)","dass":"that","sie":"she (subject of the dass-clause)","keine":"no (acc. fem.)","Zeit":"time","hatte":"had"}'::jsonb, 2, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'd3b7301f-e10a-57cd-97a3-04f557c257e6'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '5aa2d669-a812-5ddb-b1d8-0d8245a3e9d7'::uuid, 'b11f911b-9c17-4100-b0a7-4a6c905773a4'::uuid, 'Das ist das billigste Café in der Stadt.', 'That is the cheapest café in the city.', 'billigste', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'billig + ste, neuter nominative, so no extra ending after -ste.', 'billig + ste, neutrum Nominativ, keine weitere Endung.', '{"Das":"That","ist":"is","das billigste":"the cheapest","Café":"café","in der Stadt":"in the city"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '5aa2d669-a812-5ddb-b1d8-0d8245a3e9d7'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '4bcf150c-d704-594d-bb9e-76847c70bd7e'::uuid, 'b11f911b-9c17-4100-b0a7-4a6c905773a4'::uuid, 'Am liebsten fahre ich mit dem Zug.', 'I like traveling by train the most.', 'Am liebsten', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'am liebsten works as an adverb here, so it can start the sentence.', 'am liebsten ist ein Adverb und kann den Satz eröffnen.', '{"Am liebsten":"most of all","fahre ich":"I travel","mit dem Zug":"by train"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '4bcf150c-d704-594d-bb9e-76847c70bd7e'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '5e5155eb-07a8-5e36-9a06-5185b7485a9d'::uuid, 'b11f911b-9c17-4100-b0a7-4a6c905773a4'::uuid, 'Die meisten Leute mögen den neuen Film.', 'Most people like the new film.', 'Die meisten', NULL, 11, '2026-09-05T12:00:00+00:00'::timestamptz, 'die meisten Leute uses the plural superlative of viel: meiste.', 'die meisten Leute nutzt den Plural-Superlativ von viel: meiste.', '{"Die meisten Leute":"Most people","mögen":"like","den neuen Film":"the new film"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '5e5155eb-07a8-5e36-9a06-5185b7485a9d'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '603aeb2d-688d-50e2-a2a6-c0bcb93ad06d'::uuid, 'b11f911b-9c17-4100-b0a7-4a6c905773a4'::uuid, 'Dieses Café ist am teuersten in der ganzen Straße.', 'This café is the most expensive on the whole street.', 'am teuersten', NULL, 12, '2026-09-05T12:00:00+00:00'::timestamptz, 'teuer + sten after sein: -esten is only for adjectives ending in -t/-d/-z/-s/-ß/-sch, so teuer just adds -sten.', 'teuer + sten nach sein: -esten gilt nur nach -t/-d/-z/-s/-ß/-sch, teuer bekommt einfach -sten.', '{"Dieses Café":"This café","ist":"is","am teuersten":"the most expensive","in der ganzen Straße":"on the whole street"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '603aeb2d-688d-50e2-a2a6-c0bcb93ad06d'::uuid);

-- Exercises
INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0393368b-c33d-5300-b75f-a39a0226f1ed'::uuid, '34c4b3f8-a51a-47b1-9bd6-36e7c1301d68'::uuid, 4, 'fill_blank', 'Das neue Handy ist ___ als das alte. (teuer)', 'The new phone is more expensive than the old one. Comparative, no umlaut. Base form: teuer.', NULL, 'teurer', '["teurer","teurer."]'::jsonb, 'teuer drops the middle e before an ending, just like in the comparative: teurer.', 'teuer verliert das mittlere e: teurer.', NULL, 9, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'teuer → teurer (the e in the middle drops out).', 'teuer → teurer (das mittlere e fällt weg).', 'Forming the Comparative'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0393368b-c33d-5300-b75f-a39a0226f1ed'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2c5e1cce-0d9a-5dcc-8c20-247093ceac3e'::uuid, '34c4b3f8-a51a-47b1-9bd6-36e7c1301d68'::uuid, 4, 'fill_blank', 'Ich suche eine ___ Küche. (groß)', 'I am looking for a bigger kitchen. Comparative before a feminine accusative noun. Base form: groß.', NULL, 'größere', '["größere","größere."]'::jsonb, 'groß gets an umlaut (größer) plus the feminine ending -e: größere.', 'groß bekommt einen Umlaut (größer) plus die feminine Endung -e: größere.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Comparative + feminine accusative ending: größer + e = größere.', 'Komparativ + feminine Endung: größer + e = größere.', 'Comparative Endings Before a Noun in Every Case'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2c5e1cce-0d9a-5dcc-8c20-247093ceac3e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '166c2130-7ab4-5beb-b3f3-9bab04e4ded2'::uuid, '34c4b3f8-a51a-47b1-9bd6-36e7c1301d68'::uuid, 4, 'fill_blank', 'Mein Bruder ist ___ als ich. (jung)', 'My brother is younger than me. Comparative with umlaut. Base form: jung.', NULL, 'jünger', '["jünger","jünger."]'::jsonb, 'jung takes an umlaut in the comparative: jünger.', 'jung bekommt einen Umlaut: jünger.', NULL, 11, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'One-syllable adjective with u → ü: jung becomes jünger.', 'Einsilbig mit u → ü: jung wird jünger.', 'Adjectives with Umlaut Change'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '166c2130-7ab4-5beb-b3f3-9bab04e4ded2'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0286b7ea-8b41-5436-bcc6-fc72e65dda13'::uuid, '34c4b3f8-a51a-47b1-9bd6-36e7c1301d68'::uuid, 4, 'fill_blank', 'Der Kaffee hier schmeckt ___ als der Tee. (gut)', 'The coffee here tastes better than the tea. Irregular comparative. Base form: gut.', NULL, 'besser', '["besser","besser."]'::jsonb, 'gut is irregular: besser, never guter.', 'gut ist unregelmäßig: besser, nie guter.', NULL, 12, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'gut → besser is one of the three big irregulars.', 'gut → besser ist einer der drei großen Unregelmäßigen.', 'Irregular Comparatives'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0286b7ea-8b41-5436-bcc6-fc72e65dda13'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'bbd0f6b6-daf3-5163-b105-109c9042e3d9'::uuid, '34c4b3f8-a51a-47b1-9bd6-36e7c1301d68'::uuid, 5, 'fill_blank', 'Die Tage werden immer ___. (kurz)', 'The days keep getting shorter. immer + comparative, with umlaut. Base form: kurz.', NULL, 'kürzer', '["kürzer","kürzer."]'::jsonb, 'kurz takes an umlaut, and immer + comparative shows a continuing trend.', 'kurz bekommt einen Umlaut, immer + Komparativ zeigt eine Entwicklung.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'kurz → kürzer, and immer kürzer means shorter and shorter.', 'kurz → kürzer, immer kürzer heißt: jeden Tag ein bisschen kürzer.', 'Special Comparative Patterns'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'bbd0f6b6-daf3-5163-b105-109c9042e3d9'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c3bb3232-8e1f-51cd-8d8a-23186100d8d3'::uuid, '34c4b3f8-a51a-47b1-9bd6-36e7c1301d68'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wie / der andere / genauso / schnell / sein / dieser Zug]', 'Write the sentence: This train is just as fast as the other one. Equal comparison, no -er ending. Start with ''Dieser''.', NULL, 'Dieser Zug ist genauso schnell wie der andere.', '["Dieser Zug ist genauso schnell wie der andere.","Dieser Zug ist genauso schnell wie der andere"]'::jsonb, 'genauso ... wie uses the base adjective schnell, not the comparative schneller.', 'genauso ... wie benutzt die Grundform schnell, nicht schneller.', NULL, 14, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Equal comparison: genauso + base adjective + wie.', 'Gleichheit: genauso + Grundform + wie.', 'Special Comparative Patterns'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c3bb3232-8e1f-51cd-8d8a-23186100d8d3'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '400d390c-7c39-5463-a0c9-6191b8221eaf'::uuid, '34c4b3f8-a51a-47b1-9bd6-36e7c1301d68'::uuid, 5, 'sentence_building', 'Schreib den Satz: [Auto / groß / ein / brauchen / ich]', 'Write the sentence: I need a bigger car. Comparative before a neuter accusative noun. Start with ''Ich''.', NULL, 'Ich brauche ein größeres Auto.', '["Ich brauche ein größeres Auto.","Ich brauche ein größeres Auto"]'::jsonb, 'groß → größer, plus the neuter accusative ending -es: größeres.', 'groß → größer, plus die neutrale Endung -es: größeres.', NULL, 15, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Comparative + neuter accusative ending: größer + es = größeres.', 'Komparativ + neutrale Endung: größer + es = größeres.', 'Comparative Endings Before a Noun in Every Case'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '400d390c-7c39-5463-a0c9-6191b8221eaf'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2ee48412-3ad4-51d0-8f47-67bcc7bc4e5c'::uuid, '34c4b3f8-a51a-47b1-9bd6-36e7c1301d68'::uuid, 5, 'sentence_building', 'Schreib den Satz: [als / ich / etwas / jung / sein / unser / neu / Nachbar]', 'Write the sentence: Our new neighbour is a bit younger than me. etwas + comparative. Start with ''Unser''.', NULL, 'Unser neuer Nachbar ist etwas jünger als ich.', '["Unser neuer Nachbar ist etwas jünger als ich.","Unser neuer Nachbar ist etwas jünger als ich"]'::jsonb, 'etwas softens the comparative: a bit younger, not much younger.', 'etwas macht den Komparativ schwächer: etwas jünger.', NULL, 16, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Nominative masculine adjective ending on neu: neuer, plus jung → jünger.', 'Nominativ maskulin Endung bei neu: neuer, plus jung → jünger.', 'Special Comparative Patterns'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2ee48412-3ad4-51d0-8f47-67bcc7bc4e5c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f3a1fdcf-baec-5f0d-9518-9adefd62d1c2'::uuid, '34c4b3f8-a51a-47b1-9bd6-36e7c1301d68'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Er ist stärker wie sein Vater."', 'Find the error and write the sentence correctly: "Er ist stärker wie sein Vater." (als vs. wie)', NULL, 'Er ist stärker als sein Vater.', '["Er ist stärker als sein Vater.","Er ist stärker als sein Vater"]'::jsonb, 'The comparative always takes als, never wie.', 'Der Komparativ braucht immer als, nie wie.', NULL, 17, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'als = than (comparative); wie = as (equal comparison only).', 'als = Komparativ; wie = nur bei Gleichheit.', 'Using als for Comparisons'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f3a1fdcf-baec-5f0d-9518-9adefd62d1c2'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '35db95fd-7c64-5372-8e64-aaa8ca4aafc6'::uuid, '34c4b3f8-a51a-47b1-9bd6-36e7c1301d68'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Ich suche einen besser Platz."', 'Find the error and write the sentence correctly: "Ich suche einen besser Platz." (missing adjective ending before a noun)', NULL, 'Ich suche einen besseren Platz.', '["Ich suche einen besseren Platz.","Ich suche einen besseren Platz"]'::jsonb, 'Before a masculine accusative noun, the comparative needs the ending -en: besseren.', 'Vor einem maskulinen Akkusativ-Nomen braucht der Komparativ die Endung -en: besseren.', NULL, 18, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Masculine accusative ending -en: besser + en = besseren.', 'Maskulin Akkusativ Endung -en: besser + en = besseren.', 'Comparative Endings Before a Noun in Every Case'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '35db95fd-7c64-5372-8e64-aaa8ca4aafc6'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '93a3eef1-88dc-5f80-b30c-ac2c5ad2e380'::uuid, 'd0f70c42-4a0b-44ed-9279-837e0dc5bc67'::uuid, 4, 'fill_blank', 'Entweder ___ wir ins Kino, oder wir bleiben zu Hause. (gehen)', 'Either we go to the cinema, or we stay home. entweder alone: verb comes right after it. Base form: gehen.', NULL, 'gehen', '["gehen"]'::jsonb, 'entweder stands alone here, so the verb comes right after it: gehen wir.', 'entweder steht hier allein, darum kommt das Verb direkt danach: gehen wir.', NULL, 9, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'entweder alone → inversion: verb before the subject.', 'entweder allein → Inversion: Verb vor dem Subjekt.', 'Two-Part Connectors: entweder ... oder and nicht ... sondern'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '93a3eef1-88dc-5f80-b30c-ac2c5ad2e380'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '51f121be-cd07-5f0c-8f0f-067f2633ca52'::uuid, 'd0f70c42-4a0b-44ed-9279-837e0dc5bc67'::uuid, 4, 'fill_blank', 'Ich habe kein Auto, ___ ein Fahrrad. (sondern)', 'I don''t have a car, but rather a bike. Correction after kein. Base form: sondern.', NULL, 'sondern', '["sondern"]'::jsonb, 'kein signals a negative, so the correction word is sondern.', 'kein zeigt eine Verneinung, darum kommt sondern.', NULL, 10, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Negative (kein) + correction → sondern.', 'Verneinung (kein) + Korrektur → sondern.', 'Two-Part Connectors: entweder ... oder and nicht ... sondern'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '51f121be-cd07-5f0c-8f0f-067f2633ca52'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e1a7dd27-05e5-546b-b4f5-f88bf98316b5'::uuid, 'd0f70c42-4a0b-44ed-9279-837e0dc5bc67'::uuid, 4, 'fill_blank', 'Entweder bleibst du hier, ___ du kommst mit. (oder)', 'Either you stay here, or you come along. Second half of the two-part connector. Base form: oder.', NULL, 'oder', '["oder"]'::jsonb, 'entweder needs its partner word oder for the second option.', 'entweder braucht sein Partnerwort oder für die zweite Möglichkeit.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'entweder ... oder: the connector''s second half.', 'entweder gehört immer ein oder dazu.', 'Two-Part Connectors: entweder ... oder and nicht ... sondern'
