INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1b9e68b5-ada9-5338-afa8-6391995cf835'::uuid, 'd0f70c42-4a0b-44ed-9279-837e0dc5bc67'::uuid, 4, 'fill_blank', 'Wir nehmen den Bus, denn das Auto ___ kaputt. (sein)', 'We''re taking the bus because the car is broken. denn keeps normal word order. Base form: sein.', NULL, 'ist', '["ist"]'::jsonb, 'After denn, normal word order stays: das Auto ist, not ist das Auto.', 'Nach denn bleibt die normale Wortstellung: das Auto ist, nicht ist das Auto.', 'denn ändert die Wortstellung nicht.', 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'denn does not change word order: das Auto ist stays normal.', 'denn ändert die Wortstellung nicht: das Auto ist bleibt normal.', 'denn vs. weil'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1b9e68b5-ada9-5338-afa8-6391995cf835'::uuid);

