SELECT '8119bbc7-6d23-5772-a19d-c480430010f0'::uuid, 'd0f70c42-4a0b-44ed-9279-837e0dc5bc67'::uuid, 5, 'sentence_building', 'Schreib den Satz: [sie / haben / kein / Auto / sondern / ein / Fahrrad]', 'Write the sentence: She has no car, but rather a bike. Correction after kein. Start with ''Sie''.', NULL, 'Sie hat kein Auto, sondern ein Fahrrad.', '["Sie hat kein Auto, sondern ein Fahrrad.","Sie hat kein Auto, sondern ein Fahrrad"]'::jsonb, 'kein Auto is negative, so sondern introduces the correction.', 'kein Auto ist negativ, sondern bringt die Korrektur.', NULL, 15, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sie + hat + kein Auto + sondern + ein Fahrrad.', 'sie + hat + kein Auto + sondern + ein Fahrrad.', 'Two-Part Connectors: entweder ... oder and nicht ... sondern'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8119bbc7-6d23-5772-a19d-c480430010f0'::uuid);

