SELECT 'a7a08750-6135-59b9-8e8d-191ec4a1cb69'::uuid, 'd0f70c42-4a0b-44ed-9279-837e0dc5bc67'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Ich koche, und räume auf."', 'Find the error and write the sentence correctly: "Ich koche, und räume auf." (no second subject)', NULL, 'Ich koche und räume auf.', '["Ich koche und räume auf.","Ich koche und räume auf"]'::jsonb, 'There is no second subject, so no comma is used before und.', 'Es gibt kein zweites Subjekt, darum kein Komma vor und.', NULL, 17, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Compound verb, one subject: remove the comma.', 'Ein Subjekt, zwei Verben: Komma entfernen.', 'Joining Verbs Without Repeating the Subject'
