SELECT 'd109574f-85bc-5c99-beb5-0329da7901b6'::uuid, 'd0f70c42-4a0b-44ed-9279-837e0dc5bc67'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Er kauft ein Handy denn seins ist kaputt."', 'Find the error and write the sentence correctly: "Er kauft ein Handy denn seins ist kaputt." (missing comma)', NULL, 'Er kauft ein Handy, denn seins ist kaputt.', '["Er kauft ein Handy, denn seins ist kaputt.","Er kauft ein Handy, denn seins ist kaputt"]'::jsonb, 'denn joins two full clauses, so a comma is required before it.', 'denn verbindet zwei volle Sätze, darum steht davor ein Komma.', NULL, 18, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Comma required before denn between two clauses.', 'Komma vor denn zwischen zwei Sätzen ist Pflicht.', 'Comma Rules'
