SELECT 'dcf322e0-80fc-5be8-93f5-8c633600053a'::uuid, '0d1d11e3-7551-4f74-9036-df5fab56f320'::uuid, 4, 'fill_blank', 'Ich hoffe, dass ich den Bus noch erreichen ___. (werden)', 'I hope that I will still catch the bus. Future tense in a dass-clause: werden at the very end. Base form: werden.', NULL, 'werde', '["werde","werde."]'::jsonb, 'dass sends werden to the end, after the infinitive erreichen.', 'dass schickt werden ans Ende, nach dem Infinitiv erreichen.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'ich-form of werden is werde, placed after the infinitive at the very end.', 'ich-Form von werden ist werde, nach dem Infinitiv ganz am Ende.', 'Future Tense in Subordinate Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'dcf322e0-80fc-5be8-93f5-8c633600053a'::uuid);

