SELECT 'e7f0c450-a15c-5995-9a6f-99e5d6c06321'::uuid, '0d1d11e3-7551-4f74-9036-df5fab56f320'::uuid, 4, 'fill_blank', 'Nächstes Jahr ___ wir nach Spanien reisen. (werden)', 'Next year we will travel to Spain. Time-first sentence, werden in position 2. Base form: werden.', NULL, 'werden', '["werden","werden."]'::jsonb, 'wir uses werden, and it still stands in position 2 even though a time word starts the sentence.', 'wir nimmt werden, und es bleibt auf Position 2, auch wenn ein Zeitwort zuerst steht.', NULL, 10, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'wir-form of werden is werden; the infinitive reisen stays at the end.', 'wir-Form von werden ist werden; der Infinitiv reisen bleibt am Ende.', 'werden Conjugation'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e7f0c450-a15c-5995-9a6f-99e5d6c06321'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0a0cfa18-963e-510a-be12-98309d93a27e'::uuid, '0d1d11e3-7551-4f74-9036-df5fab56f320'::uuid, 4, 'fill_blank', '___ du mir bei den Hausaufgaben helfen? (werden)', 'Will you help me with my homework? Question, du-form of werden. Base form: werden.', NULL, 'Wirst', '["Wirst","wirst"]'::jsonb, 'du-form of werden is wirst, at the start of a question.', 'du-Form von werden ist wirst, am Anfang der Frage.', NULL, 11, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'In a yes/no question, the conjugated verb comes first: Wirst du ... ?', 'In der Ja/Nein-Frage steht das konjugierte Verb zuerst: Wirst du ... ?', 'werden Conjugation'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0a0cfa18-963e-510a-be12-98309d93a27e'::uuid);

