SELECT '753b0e26-d166-5c03-96c6-79e97798d09f'::uuid, '0d1d11e3-7551-4f74-9036-df5fab56f320'::uuid, 4, 'fill_blank', 'Die Kinder ___ im Sommer viel draußen spielen. (werden)', 'The children will play outside a lot in summer. sie-plural form of werden. Base form: werden.', NULL, 'werden', '["werden","werden."]'::jsonb, 'die Kinder is plural, so it takes werden, with the infinitive spielen at the end.', 'die Kinder ist Plural: werden, mit dem Infinitiv spielen am Ende.', NULL, 12, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Plural subject takes werden, and the infinitive spielen stays at the very end.', 'Plural-Subjekt nimmt werden, der Infinitiv spielen bleibt ganz am Ende.', 'Future Tense Structure'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '753b0e26-d166-5c03-96c6-79e97798d09f'::uuid);

