SELECT '8d88edf3-ce6b-5829-8ea3-a2f5154261d6'::uuid, '0d1d11e3-7551-4f74-9036-df5fab56f320'::uuid, 5, 'fill_blank', 'Ich verspreche, dass ich das Zimmer aufräumen ___. (werden)', 'I promise that I will clean up the room. Future tense in a dass-clause, separable verb infinitive. Base form: werden.', NULL, 'werde', '["werde","werde."]'::jsonb, 'dass sends the whole verb group to the end: aufräumen (infinitive) then werde.', 'dass schickt die ganze Verbgruppe ans Ende: aufräumen, dann werde.', NULL, 13, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'ich-form of werden is werde, placed after the infinitive at the very end.', 'ich-Form von werden ist werde, nach dem Infinitiv ganz am Ende.', 'Future Tense in Subordinate Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8d88edf3-ce6b-5829-8ea3-a2f5154261d6'::uuid);

