SELECT 'e9369e3f-d200-5e1f-b349-7857cc591e87'::uuid, '0d1d11e3-7551-4f74-9036-df5fab56f320'::uuid, 5, 'sentence_building', 'Schreib den Satz: [reparieren / das Auto / bis Freitag / werden / wir]', 'Write the sentence: We will repair the car by Friday. werden in position 2, infinitive at the end. Start with ''Wir''.', NULL, 'Wir werden das Auto bis Freitag reparieren.', '["Wir werden das Auto bis Freitag reparieren.","Wir werden das Auto bis Freitag reparieren","Wir werden bis Freitag das Auto reparieren.","Wir werden bis Freitag das Auto reparieren"]'::jsonb, 'werden stays in position 2; the infinitive reparieren goes all the way to the end.', 'werden bleibt auf Position 2; der Infinitiv reparieren steht ganz am Ende.', NULL, 14, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Standard Futur I order: subject, werden, everything else, infinitive last.', 'Normale Futur-I-Reihenfolge: Subjekt, werden, alles andere, Infinitiv zuletzt.', 'Future Tense Structure'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e9369e3f-d200-5e1f-b349-7857cc591e87'::uuid);

