INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5f5d0cea-c92a-5153-b16b-ac8d32554846'::uuid, '0d1d11e3-7551-4f74-9036-df5fab56f320'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Ich glaube, dass er wird kommen."', 'Find the error and write the sentence correctly: "Ich glaube, dass er wird kommen." (werden must stand at the end)', NULL, 'Ich glaube, dass er kommen wird.', '["Ich glaube, dass er kommen wird.","Ich glaube, dass er kommen wird"]'::jsonb, 'In a dass-clause, werden goes to the very end, after the infinitive kommen.', 'Im dass-Satz steht werden ganz am Ende, nach dem Infinitiv kommen.', NULL, 17, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'dass sends the whole verb group to the end: kommen wird.', 'dass schickt die ganze Verbgruppe ans Ende: kommen wird.', 'Future Tense in Subordinate Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5f5d0cea-c92a-5153-b16b-ac8d32554846'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'cbfc7f8c-ac97-5feb-9192-a169c5c41c4d'::uuid, '0d1d11e3-7551-4f74-9036-df5fab56f320'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Du wirst das verstehen bald."', 'Find the error and write the sentence correctly: "Du wirst das verstehen bald." (infinitive must stand at the very end)', NULL, 'Du wirst das bald verstehen.', '["Du wirst das bald verstehen.","Du wirst das bald verstehen"]'::jsonb, 'The infinitive verstehen must stand at the very end; the time word bald comes before it.', 'Der Infinitiv verstehen steht ganz am Ende; das Zeitwort bald kommt davor.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'werden behaves like a modal: the infinitive stays at the very end of the sentence.', 'werden verhält sich wie ein Modalverb: der Infinitiv bleibt ganz am Ende.', 'Mistakes with Futur I'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'cbfc7f8c-ac97-5feb-9192-a169c5c41c4d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6aea1912-3a91-52ed-aa75-da0ea7aa24cc'::uuid, '7e275945-433d-4e15-a87b-e33943d9fc80'::uuid, 4, 'fill_blank', 'Ich habe ___ das Gesicht gewaschen. (sich)', 'I washed my face. Perfekt, ich-form, dative reflexive with a body-part object. Base form: sich.', NULL, 'mir', '["mir"]'::jsonb, 'das Gesicht is the object, so ich takes the dative reflexive: mir.', 'ich → mir, weil ein Objekt da ist.', NULL, 9, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Object present (das Gesicht) → dative reflexive mir.', 'Objekt vorhanden (das Gesicht) → Dativ: mir.', 'More Reflexive Verbs: With or Without a Body Part'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6aea1912-3a91-52ed-aa75-da0ea7aa24cc'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3539d8cd-d136-5d2c-bcc1-6e208bd1d2ee'::uuid, '7e275945-433d-4e15-a87b-e33943d9fc80'::uuid, 4, 'fill_blank', 'Wir haben ___ für den Ausflug angemeldet. (sich)', 'We signed up for the trip. Perfekt, wir-form reflexive pronoun after haben. Base form: sich.', NULL, 'uns', '["uns"]'::jsonb, 'wir takes uns, and it comes directly after haben.', 'wir → uns, direkt nach haben.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'wir → uns, placed right after haben.', 'wir → uns, direkt nach haben.', 'Reflexive Verbs in Perfekt and with Modal Verbs'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3539d8cd-d136-5d2c-bcc1-6e208bd1d2ee'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '979c1c62-36e2-5c90-a1ec-c8e4ca376225'::uuid, '7e275945-433d-4e15-a87b-e33943d9fc80'::uuid, 4, 'fill_blank', 'Du musst ___ beeilen, der Zug fährt gleich. (sich)', 'You have to hurry, the train leaves soon. Modal verb, du-form reflexive pronoun. Base form: sich.', NULL, 'dich', '["dich"]'::jsonb, 'du takes dich, placed right after the modal musst.', 'du → dich, direkt nach musst.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'du → dich, right after the modal verb.', 'du → dich, direkt nach dem Modalverb.', 'Reflexive Verbs in Perfekt and with Modal Verbs'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '979c1c62-36e2-5c90-a1ec-c8e4ca376225'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0125bc18-d799-5a7f-83d8-d47350ad333d'::uuid, '7e275945-433d-4e15-a87b-e33943d9fc80'::uuid, 4, 'fill_blank', 'Sie hat ___ schön angezogen. (sich)', 'She got dressed up nicely. Perfekt, sie-form (she), accusative reflexive, no separate object. Base form: sich.', NULL, 'sich', '["sich"]'::jsonb, 'No object is named, so sie takes the accusative reflexive: sich.', 'Hier gibt es kein Objekt, darum steht der Akkusativ: sich.', 'Kein Objekt im Satz: Akkusativ.', 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'No object → accusative reflexive sich.', 'Kein Objekt → Akkusativ: sich.', 'More Reflexive Verbs: With or Without a Body Part'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0125bc18-d799-5a7f-83d8-d47350ad333d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1ec928a4-498a-5bc1-acb9-d5d8e9cf4ec8'::uuid, '7e275945-433d-4e15-a87b-e33943d9fc80'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / sich anmelden / für / der Kurs]', 'Write the sentence: I signed up for the course. Perfekt with haben, reflexive pronoun after haben. Start with ''Ich''.', NULL, 'Ich habe mich für den Kurs angemeldet.', '["Ich habe mich für den Kurs angemeldet.","Ich habe mich für den Kurs angemeldet"]'::jsonb, 'mich follows habe, and the separable participle angemeldet goes to the end.', 'mich steht nach habe, angemeldet steht am Ende.', NULL, 13, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'ich + habe + mich + für den Kurs + angemeldet.', 'ich + habe + mich + für den Kurs + angemeldet.', 'Reflexive Verbs in Perfekt and with Modal Verbs'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1ec928a4-498a-5bc1-acb9-d5d8e9cf4ec8'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c150aa45-ac97-5036-bae8-a5ed6882494a'::uuid, '7e275945-433d-4e15-a87b-e33943d9fc80'::uuid, 5, 'sentence_building', 'Schreib den Satz: [er / müssen / sich beeilen]', 'Write the sentence: He has to hurry. Modal verb + reflexive verb. Start with ''Er''.', NULL, 'Er muss sich beeilen.', '["Er muss sich beeilen.","Er muss sich beeilen"]'::jsonb, 'sich comes right after the modal muss, beeilen stays an infinitive at the end.', 'sich steht nach muss, beeilen bleibt Infinitiv am Ende.', NULL, 14, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'er + muss + sich + beeilen.', 'er + muss + sich + beeilen.', 'Reflexive Verbs in Perfekt and with Modal Verbs'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c150aa45-ac97-5036-bae8-a5ed6882494a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '666d3e64-2dc4-57fd-a63d-09dbc044a906'::uuid, '7e275945-433d-4e15-a87b-e33943d9fc80'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / sich waschen / die Hände]', 'Write the sentence: We wash our hands. Dative reflexive with a body-part object. Start with ''Wir''.', NULL, 'Wir waschen uns die Hände.', '["Wir waschen uns die Hände.","Wir waschen uns die Hände"]'::jsonb, 'die Hände is the object, so wir takes the dative reflexive: uns.', 'wir → uns, weil ein Objekt da ist.', NULL, 15, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Object present → dative reflexive uns.', 'Objekt vorhanden → Dativ: uns.', 'More Reflexive Verbs: With or Without a Body Part'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '666d3e64-2dc4-57fd-a63d-09dbc044a906'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '529dd3a7-92f5-5e2d-af26-5e44ef3fe7e6'::uuid, '7e275945-433d-4e15-a87b-e33943d9fc80'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Ich habe angemeldet mich für den Kurs."', 'Find the error and write the sentence correctly: "Ich habe angemeldet mich für den Kurs." (Perfekt, reflexive pronoun position)', NULL, 'Ich habe mich für den Kurs angemeldet.', '["Ich habe mich für den Kurs angemeldet.","Ich habe mich für den Kurs angemeldet"]'::jsonb, 'mich must come right after habe, not at the end of the sentence.', 'mich muss direkt nach habe stehen, nicht am Satzende.', NULL, 16, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Reflexive pronoun position: right after the conjugated haben.', 'Das Reflexivpronomen steht direkt nach dem konjugierten haben.', 'Mistakes with Reflexive Verbs in Perfekt and with Modals'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '529dd3a7-92f5-5e2d-af26-5e44ef3fe7e6'::uuid);

