SELECT 'e7fd954a-49b6-5b20-ac7d-9155c5373e0a'::uuid, '7e275945-433d-4e15-a87b-e33943d9fc80'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Ich rufe an, weil ich habe mich verspätet."', 'Find the error and write the sentence correctly: "Ich rufe an, weil ich habe mich verspätet." (weil clause, verb-final)', NULL, 'Ich rufe an, weil ich mich verspätet habe.', '["Ich rufe an, weil ich mich verspätet habe.","Ich rufe an, weil ich mich verspätet habe"]'::jsonb, 'In a weil clause, habe moves to the very end, after mich verspätet.', 'Im weil-Satz steht habe ganz am Ende, nach mich verspätet.', NULL, 17, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'weil + Subjekt + mich verspätet + habe (verb-final).', 'weil + Subjekt + mich verspätet + habe (Verb am Ende).', 'Mistakes with Reflexive Verbs in Perfekt and with Modals'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e7fd954a-49b6-5b20-ac7d-9155c5373e0a'::uuid);

