SELECT '8fcf1600-5b2c-5828-a10f-99ab89d9d31f'::uuid, '7e275945-433d-4e15-a87b-e33943d9fc80'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Er hat die Jacke sich angezogen."', 'Find the error and write the sentence correctly: "Er hat die Jacke sich angezogen." (dative reflexive position)', NULL, 'Er hat sich die Jacke angezogen.', '["Er hat sich die Jacke angezogen.","Er hat sich die Jacke angezogen"]'::jsonb, 'sich must come right after hat, before the object die Jacke.', 'sich muss direkt nach hat stehen, vor dem Objekt die Jacke.', NULL, 18, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Reflexive pronoun before the object: hat + sich + die Jacke.', 'Reflexivpronomen vor dem Objekt: hat + sich + die Jacke.', 'Mistakes with Reflexive Verbs in Perfekt and with Modals'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8fcf1600-5b2c-5828-a10f-99ab89d9d31f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ba9dbaeb-fa22-57a5-9bd7-835abf70a19e'::uuid, '71b4f297-92c2-47e9-b5f1-feb784b30226'::uuid, 4, 'fill_blank', 'Es ___ gestern ein großes Problem. (geben)', 'There was a big problem yesterday. Fixed impersonal chunk. Base form: geben.', NULL, 'gab', '["gab"]'::jsonb, 'es gab never changes for number; it is always gab.', 'es gab ändert sich nie: immer gab.', NULL, 9, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Fixed chunk: es + gab.', 'Fester Ausdruck: es + gab.', 'es gab, es war + Weather and Time (Storytelling)'
