SELECT '51a2974a-8c53-5153-8e22-8cf4d682ece9'::uuid, '71b4f297-92c2-47e9-b5f1-feb784b30226'::uuid, 4, 'fill_blank', 'Ich bin zu Hause geblieben, weil ich krank ___. (sein)', 'I stayed home because I was sick. weil clause, verb-final. Base form: sein.', NULL, 'war', '["war"]'::jsonb, 'In a weil clause, the verb goes to the end: war.', 'Im weil-Satz steht das Verb am Ende: war.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'weil clause, ich-form of sein: war, placed at the end.', 'weil-Satz, ich-Form von sein: war, am Ende.', 'war and hatte in weil/dass/wenn Clauses'
