SELECT '386ce5a3-677f-53a2-991f-2bef71619b0c'::uuid, '71b4f297-92c2-47e9-b5f1-feb784b30226'::uuid, 4, 'fill_blank', 'Sie hat gesagt, dass sie keine Zeit ___. (haben)', 'She said that she had no time. dass clause, verb-final. Base form: haben.', NULL, 'hatte', '["hatte"]'::jsonb, 'In a dass clause, the verb goes to the end: hatte.', 'Im dass-Satz steht das Verb am Ende: hatte.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'dass clause, sie-form of haben: hatte, placed at the end.', 'dass-Satz, sie-Form von haben: hatte, am Ende.', 'war and hatte in weil/dass/wenn Clauses'
