SELECT 'f64e96e7-2339-504c-bbcb-1ebea0ca3a6f'::uuid, '71b4f297-92c2-47e9-b5f1-feb784b30226'::uuid, 4, 'fill_blank', 'Wenn das Wetter schlecht ___, sind wir zu Hause geblieben. (sein)', 'Whenever the weather was bad, we stayed home. wenn clause, verb-final, repeated past. Base form: sein.', NULL, 'war', '["war"]'::jsonb, 'wenn sends war to the end of its own clause; this describes repeated situations.', 'wenn schickt war in seinem Nebensatz ans Ende; es geht um Wiederholung.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Habitual wenn + war at the end of the clause.', 'wenn für wiederholte Situationen: war steht am Ende.', 'war and hatte in weil/dass/wenn Clauses'
