SELECT '22286bf7-be1d-5053-8b66-be6d74b40dcf'::uuid, '71b4f297-92c2-47e9-b5f1-feb784b30226'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ihr / sein / müde / weil / haben / viel / Arbeit]', 'Write the sentence: You all were tired because you had a lot of work. war + weil + hattet. Start with ''Ihr''.', NULL, 'Ihr wart müde, weil ihr viel Arbeit hattet.', '["Ihr wart müde, weil ihr viel Arbeit hattet.","Ihr wart müde, weil ihr viel Arbeit hattet"]'::jsonb, 'Both clauses use war/hatte; the weil clause sends hattet to the end.', 'Beide Sätze nutzen war/hatte; der weil-Satz schickt hattet ans Ende.', NULL, 13, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'ihr → wart / hattet; weil sends hattet to the end.', 'ihr → wart / hattet; weil schickt hattet ans Ende.', 'war and hatte in weil/dass/wenn Clauses'
