SELECT '58c67382-5c6b-5ba1-8c14-8bf3e6d032f2'::uuid, '71b4f297-92c2-47e9-b5f1-feb784b30226'::uuid, 5, 'sentence_building', 'Schreib den Satz: [es / geben / gestern / kein Brot]', 'Write the sentence: There was no bread yesterday. Fixed chunk es gab. Start with ''Es''.', NULL, 'Es gab gestern kein Brot.', '["Es gab gestern kein Brot.","Es gab gestern kein Brot"]'::jsonb, 'es gab is fixed and does not change for the negative kein.', 'es gab ist fest und ändert sich nicht durch kein.', NULL, 14, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'es + gab + gestern + kein Brot.', 'es + gab + gestern + kein Brot.', 'es gab, es war + Weather and Time (Storytelling)'
