SELECT 'b0cd90c6-b6cc-5527-8854-f19a09fa2539'::uuid, '71b4f297-92c2-47e9-b5f1-feb784b30226'::uuid, 5, 'sentence_building', 'Schreib den Satz: [du / sagen / dass / du / haben / kein / Hunger]', 'Write the sentence: You said that you weren''t hungry. Perfekt + dass + hattest. Start with ''Du''.', NULL, 'Du hast gesagt, dass du keinen Hunger hattest.', '["Du hast gesagt, dass du keinen Hunger hattest.","Du hast gesagt, dass du keinen Hunger hattest"]'::jsonb, 'The dass clause sends hattest to the end.', 'Der dass-Satz schickt hattest ans Ende.', NULL, 15, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Hauptsatz (Perfekt) + dass + Subjekt + keinen Hunger + hattest.', 'Hauptsatz (Perfekt) + dass + Subjekt + keinen Hunger + hattest.', 'war and hatte in weil/dass/wenn Clauses'
