SELECT 'd2072227-0a14-548a-9cc9-a41aae0da3ee'::uuid, '71b4f297-92c2-47e9-b5f1-feb784b30226'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Es waren sehr kalt im Winter."', 'Find the error and write the sentence correctly: "Es waren sehr kalt im Winter." (impersonal es war)', NULL, 'Es war sehr kalt im Winter.', '["Es war sehr kalt im Winter.","Es war sehr kalt im Winter"]'::jsonb, 'es war is always singular; waren is wrong here.', 'es war ist immer Singular, waren ist hier falsch.', NULL, 16, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Impersonal es always takes the singular: war.', 'Unpersönliches es steht immer im Singular: war.', 'Mistakes with war, hatte and es gab'
