INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '9d02b4b9-597f-522a-b98c-86a4d445456a'::uuid, '71b4f297-92c2-47e9-b5f1-feb784b30226'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Weil du hattest Fieber, warst du im Bett."', 'Find the error and write the sentence correctly: "Weil du hattest Fieber, warst du im Bett." (verb-final in a weil clause)', NULL, 'Weil du Fieber hattest, warst du im Bett.', '["Weil du Fieber hattest, warst du im Bett.","Weil du Fieber hattest, warst du im Bett"]'::jsonb, 'In a weil clause, hattest goes all the way to the end.', 'Im weil-Satz steht hattest ganz am Ende.', NULL, 17, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'weil du Fieber hattest — hattest at the very end.', 'weil du Fieber hattest — hattest ganz am Ende.', 'Mistakes with war, hatte and es gab'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '9d02b4b9-597f-522a-b98c-86a4d445456a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b44fe372-9113-587b-9fd8-50617404b507'::uuid, '71b4f297-92c2-47e9-b5f1-feb784b30226'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Es gaben keine Milch mehr."', 'Find the error and write the sentence correctly: "Es gaben keine Milch mehr." (impersonal es gab)', NULL, 'Es gab keine Milch mehr.', '["Es gab keine Milch mehr.","Es gab keine Milch mehr"]'::jsonb, 'es gab never changes for plural; gaben is wrong.', 'es gab ändert sich nie im Plural; gaben ist falsch.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Fixed chunk: es gab, never es gaben.', 'Fester Ausdruck: es gab, nie es gaben.', 'Mistakes with war, hatte and es gab'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b44fe372-9113-587b-9fd8-50617404b507'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '811556fe-b23e-5296-9864-939592c4ef18'::uuid, '8e19f108-0aac-4124-884b-1eebe937c954'::uuid, 4, 'fill_blank', 'Ich glaube, dass sie heute Abend ___. (arbeiten)', 'I think she is working this evening. Verb-final position, present tense, sie-form. Base form: arbeiten.', NULL, 'arbeitet', '["arbeitet","arbeitet."]'::jsonb, 'dass sends the conjugated verb to the end of the clause: arbeitet.', 'Nach dass steht das Verb am Ende: arbeitet.', NULL, 16, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Subordinate clause with dass: verb-final, sie-form of arbeiten is arbeitet.', 'Nebensatz mit dass: Verbendstellung, sie-Form von arbeiten ist arbeitet.', 'The Verb-Final Rule'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '811556fe-b23e-5296-9864-939592c4ef18'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a67e9cc4-526f-5360-affb-d82101bfb05a'::uuid, '8e19f108-0aac-4124-884b-1eebe937c954'::uuid, 4, 'fill_blank', 'Wir gehen nicht spazieren, weil es zu kalt ___. (sein)', 'We are not going for a walk because it is too cold. Verb-final position, es-form. Base form: sein.', NULL, 'ist', '["ist","ist."]'::jsonb, 'weil sends the conjugated verb to the end: kalt ist.', 'Nach weil steht das Verb am Ende: kalt ist.', NULL, 17, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Subordinate clause with weil: verb-final, es-form of sein is ist.', 'Nebensatz mit weil: Verbendstellung, es-Form von sein ist ist.', 'The Verb-Final Rule'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a67e9cc4-526f-5360-affb-d82101bfb05a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '50e1a7be-0e13-5d4a-a216-d7ef95e61166'::uuid, '8e19f108-0aac-4124-884b-1eebe937c954'::uuid, 4, 'fill_blank', 'Wenn du Hunger ___, koche ich Nudeln. (haben)', 'If you are hungry, I will cook pasta. Verb-final position in the wenn-clause, du-form. Base form: haben.', NULL, 'hast', '["hast","hast,"]'::jsonb, 'The wenn-clause sends the verb to the end: Hunger hast.', 'Der wenn-Satz schickt das Verb ans Ende: Hunger hast.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Subordinate clause with wenn: verb-final, du-form of haben is hast.', 'Nebensatz mit wenn: Verbendstellung, du-Form von haben ist hast.', 'The Verb-Final Rule'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '50e1a7be-0e13-5d4a-a216-d7ef95e61166'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '56db7feb-96ec-5a3e-a083-ae5a425217ed'::uuid, '8e19f108-0aac-4124-884b-1eebe937c954'::uuid, 4, 'fill_blank', 'Ich weiß nicht, ob das Geschäft samstags ___. (öffnen)', 'I don''t know if the shop opens on Saturdays. Verb-final position, es-form (das Geschäft). Base form: öffnen.', NULL, 'öffnet', '["öffnet","öffnet."]'::jsonb, 'ob sends the conjugated verb to the end: samstags öffnet.', 'Nach ob steht das Verb am Ende: samstags öffnet.', NULL, 19, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Subordinate clause with ob: verb-final, das Geschäft takes öffnet.', 'Nebensatz mit ob: Verbendstellung, das Geschäft nimmt öffnet.', 'The Verb-Final Rule'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '56db7feb-96ec-5a3e-a083-ae5a425217ed'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '581f26db-29d6-5ec3-985d-f12d42fe90fd'::uuid, '8e19f108-0aac-4124-884b-1eebe937c954'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Sie sagt, dass sie sich muss beeilen."', 'Find the error and write the sentence correctly: "Sie sagt, dass sie sich muss beeilen." (the modal verb must stand at the very end)', NULL, 'Sie sagt, dass sie sich beeilen muss.', '["Sie sagt, dass sie sich beeilen muss.","Sie sagt, dass sie sich beeilen muss"]'::jsonb, 'Modal + infinitive in a subordinate clause: infinitive first, modal last.', 'Modalverb + Infinitiv im Nebensatz: erst der Infinitiv, dann das Modalverb.', NULL, 20, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sie-form of müssen is muss, and it goes after beeilen at the very end.', 'sie-Form von müssen ist muss, ganz am Ende nach beeilen.', 'Word Order Patterns in Subordinate Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '581f26db-29d6-5ec3-985d-f12d42fe90fd'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3365cf4d-444f-5603-8c5e-1aea561f0fef'::uuid, '8e19f108-0aac-4124-884b-1eebe937c954'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Er hofft, dass es morgen nicht wird regnen."', 'Find the error and write the sentence correctly: "Er hofft, dass es morgen nicht wird regnen." (werden must stand at the very end, after the infinitive)', NULL, 'Er hofft, dass es morgen nicht regnen wird.', '["Er hofft, dass es morgen nicht regnen wird.","Er hofft, dass es morgen nicht regnen wird"]'::jsonb, 'Future tense in a subordinate clause: infinitive (regnen) then werden at the very end.', 'Futur im Nebensatz: Infinitiv (regnen), dann werden ganz am Ende.', NULL, 21, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'dass sends the whole verb group to the end: infinitive first, werden last.', 'dass schickt die ganze Verbgruppe ans Ende: erst Infinitiv, dann werden.', 'Verb Order in Subordinate Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3365cf4d-444f-5603-8c5e-1aea561f0fef'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0240835f-e0be-503e-bea1-5442f745b0a0'::uuid, '8e19f108-0aac-4124-884b-1eebe937c954'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ankommen / pünktlich / der Zug / ob / nicht / wissen / wir]', 'Write the sentence: We don''t know if the train arrives on time. ankommen is separable and rejoins at the end. Start with ''Wir''.', NULL, 'Wir wissen nicht, ob der Zug pünktlich ankommt.', '["Wir wissen nicht, ob der Zug pünktlich ankommt.","Wir wissen nicht, ob der Zug pünktlich ankommt"]'::jsonb, 'ankommen splits in a main clause but reunites as one word at the end of the ob-clause: ankommt.', 'ankommen trennt sich im Hauptsatz, im ob-Satz steht es wieder zusammen: ankommt.', NULL, 22, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Separable verbs reunite at the end of a subordinate clause: an + kommt = ankommt.', 'Trennbare Verben vereinigen sich im Nebensatz: an + kommt = ankommt.', 'Word Order Patterns in Subordinate Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0240835f-e0be-503e-bea1-5442f745b0a0'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4ad481b3-50d2-515a-bba3-5bb72545449a'::uuid, '8e19f108-0aac-4124-884b-1eebe937c954'::uuid, 5, 'sentence_building', 'Schreib den Satz: [kaufen (Perfekt) / ein neues Auto / dass / sie / erzählen / sie]', 'Write the sentence: She says that she bought a new car. Perfect tense, participle + auxiliary at the end. Start with ''Sie''.', NULL, 'Sie erzählt, dass sie ein neues Auto gekauft hat.', '["Sie erzählt, dass sie ein neues Auto gekauft hat.","Sie erzählt, dass sie ein neues Auto gekauft hat"]'::jsonb, 'Perfect tense in a subordinate clause: participle (gekauft) then the auxiliary hat, both at the end.', 'Perfekt im Nebensatz: Partizip (gekauft), dann hat, beide am Ende.', NULL, 23, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'kaufen forms Perfekt with haben: gekauft hat, and both go to the end after dass.', 'kaufen bildet das Perfekt mit haben: gekauft hat, beide am Ende nach dass.', 'Perfect Tense in Subordinate Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4ad481b3-50d2-515a-bba3-5bb72545449a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '74a78c3f-f2f9-5371-9010-239201685d7f'::uuid, '8e19f108-0aac-4124-884b-1eebe937c954'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Ich hoffe, dass er bald kommt zurück."', 'Find the error and write the sentence correctly: "Ich hoffe, dass er bald kommt zurück." (separable verb zurückkommen)', NULL, 'Ich hoffe, dass er bald zurückkommt.', '["Ich hoffe, dass er bald zurückkommt.","Ich hoffe, dass er bald zurückkommt"]'::jsonb, 'zurückkommen is separable and must reunite as one word at the very end of the dass-clause.', 'zurückkommen ist trennbar und steht im dass-Satz wieder zusammen am Ende.', NULL, 24, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The prefix zurück- must not stay separate; the whole verb zurückkommt goes to the end.', 'Das Präfix zurück- bleibt nicht getrennt; das ganze Verb zurückkommt steht am Ende.', 'Word Order Patterns in Subordinate Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '74a78c3f-f2f9-5371-9010-239201685d7f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'dca49156-2694-5849-89a3-ae1ad87954dd'::uuid, '8e19f108-0aac-4124-884b-1eebe937c954'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Er ist froh, dass er ist nach Hause gegangen."', 'Find the error and write the sentence correctly: "Er ist froh, dass er ist nach Hause gegangen." (Perfekt with sein must stand at the very end)', NULL, 'Er ist froh, dass er nach Hause gegangen ist.', '["Er ist froh, dass er nach Hause gegangen ist.","Er ist froh, dass er nach Hause gegangen ist"]'::jsonb, 'Perfect tense with sein in a subordinate clause: participle (gegangen) then the auxiliary ist, both at the end.', 'Perfekt mit sein im Nebensatz: Partizip (gegangen), dann ist, beide am Ende.', NULL, 25, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'gehen forms Perfekt with sein: gegangen ist, and both go to the end after dass.', 'gehen bildet das Perfekt mit sein: gegangen ist, beide am Ende nach dass.', 'Perfect Tense in Subordinate Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'dca49156-2694-5849-89a3-ae1ad87954dd'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '84f4463f-f964-5596-b0d2-744342cde531'::uuid, '0bec80db-6066-4d73-a4f1-29ef6c75c0d5'::uuid, 4, 'fill_blank', 'Ich glaube, dass er das Auto verkauft ___. (haben)', 'I believe he has sold the car. dass clause, Perfekt, verb-final. Base form: haben.', NULL, 'hat', '["hat"]'::jsonb, 'In a dass clause, the auxiliary hat goes all the way to the end.', 'Im dass-Satz steht das Hilfsverb hat ganz am Ende.', NULL, 16, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Perfekt in a dass clause: participle, then hat at the very end.', 'Perfekt im dass-Satz: Partizip, dann hat ganz am Ende.', 'Common Subordinating Conjunctions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '84f4463f-f964-5596-b0d2-744342cde531'::uuid);

