SELECT '303d6b14-6511-5f1c-b528-6c402f6ba3bc'::uuid, '0bec80db-6066-4d73-a4f1-29ef6c75c0d5'::uuid, 4, 'fill_blank', 'Wir bleiben zu Hause, wenn es zu kalt ___. (sein)', 'We stay home if it is too cold. wenn clause, verb-final, present tense. Base form: sein.', NULL, 'ist', '["ist"]'::jsonb, 'wenn sends the present-tense verb ist to the end of its clause.', 'wenn schickt das Präsensverb ist im Nebensatz ans Ende.', NULL, 17, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'es ist → verb-final after wenn: kalt ist.', 'es ist → Verb ans Ende nach wenn: kalt ist.', 'Word Order in Subordinate Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '303d6b14-6511-5f1c-b528-6c402f6ba3bc'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '73740eaa-489c-5019-85aa-2452f7967e22'::uuid, '0bec80db-6066-4d73-a4f1-29ef6c75c0d5'::uuid, 4, 'fill_blank', 'Ich weiß nicht, ob er das Zimmer schon ___ hat. (putzen)', 'I don''t know if he has already cleaned the room. ob clause, Perfekt participle. Base form: putzen.', NULL, 'geputzt', '["geputzt"]'::jsonb, 'The participle geputzt comes right before hat, which stays at the end.', 'Das Partizip geputzt steht direkt vor dem satzfinalen hat.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'putzen → geputzt, placed before the clause-final hat.', 'putzen → geputzt, vor dem satzfinalen hat.', 'Common Subordinating Conjunctions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '73740eaa-489c-5019-85aa-2452f7967e22'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'cdf2d12e-ff6e-562b-8307-9506fa21f63d'::uuid, '0bec80db-6066-4d73-a4f1-29ef6c75c0d5'::uuid, 4, 'fill_blank', 'Er fragt, ob ich ihm helfen ___. (können)', 'He asks if I can help him. ob clause with a modal verb, verb-final. Base form: können.', NULL, 'kann', '["kann"]'::jsonb, 'The modal kann goes to the very end, after the infinitive helfen.', 'Das Modalverb kann steht ganz am Ende, nach dem Infinitiv helfen.', NULL, 19, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'ich-form of können in an ob clause: kann, at the end.', 'ich-Form von können im ob-Satz: kann, am Ende.', 'Word Order in Subordinate Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'cdf2d12e-ff6e-562b-8307-9506fa21f63d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '666583ba-c8d4-5d09-bf7c-6dab24c66cb7'::uuid, '0bec80db-6066-4d73-a4f1-29ef6c75c0d5'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / wissen / dass / du / haben / recht]', 'Write the sentence: I know that you are right. dass clause, verb-final. Start with ''Ich''.', NULL, 'Ich weiß, dass du recht hast.', '["Ich weiß, dass du recht hast.","Ich weiß, dass du recht hast","Ich weiß, dass du Recht hast.","Ich weiß, dass du Recht hast"]'::jsonb, 'du needs hast, and dass sends it to the end of its clause.', 'du → hast, und dass schickt hast im Nebensatz ans Ende.', NULL, 20, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'ich weiß, dass + Subjekt + recht + hast.', 'ich weiß, dass + Subjekt + recht + hast.', 'Common Subordinating Conjunctions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '666583ba-c8d4-5d09-bf7c-6dab24c66cb7'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
