WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6ccbf0bf-c1b7-596c-b595-54a138d4346e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a0aff69d-9481-53b0-963c-4bf67be07a99'::uuid, '0bec80db-6066-4d73-a4f1-29ef6c75c0d5'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / hoffen / dass / du / heute / anrufen]', 'Write the sentence: I hope that you''ll call today. dass clause, separable verb reunites at the end. Start with ''Ich''.', NULL, 'Ich hoffe, dass du heute anrufst.', '["Ich hoffe, dass du heute anrufst.","Ich hoffe, dass du heute anrufst"]'::jsonb, 'anrufen reunites as one word at the end of the dass clause: anrufst.', 'anrufen bleibt im dass-Satz zusammen und steht am Ende: anrufst.', NULL, 22, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'dass + Subjekt + heute + anrufst (separable verb reunited).', 'dass + Subjekt + heute + anrufst (trennbares Verb bleibt zusammen).', 'Separable Verbs in Subordinate Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a0aff69d-9481-53b0-963c-4bf67be07a99'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f3fc52c3-d02b-5589-8d9c-5327caaa2bb1'::uuid, '0bec80db-6066-4d73-a4f1-29ef6c75c0d5'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Ich glaube, dass sie wohnt in Berlin."', 'Find the error and write the sentence correctly: "Ich glaube, dass sie wohnt in Berlin." (word order in a dass clause)', NULL, 'Ich glaube, dass sie in Berlin wohnt.', '["Ich glaube, dass sie in Berlin wohnt.","Ich glaube, dass sie in Berlin wohnt"]'::jsonb, 'In a dass clause, the verb wohnt must move to the end.', 'Im dass-Satz muss das Verb wohnt ans Ende.', NULL, 23, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'dass + Subjekt + in Berlin + wohnt.', 'dass + Subjekt + in Berlin + wohnt.', 'Common Subordinate Clause Mistakes'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f3fc52c3-d02b-5589-8d9c-5327caaa2bb1'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b2975b84-c98b-5383-b7d4-d26308058d07'::uuid, '0bec80db-6066-4d73-a4f1-29ef6c75c0d5'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Weil er hat keine Zeit, kommt er nicht."', 'Find the error and write the sentence correctly: "Weil er hat keine Zeit, kommt er nicht." (word order in a weil clause)', NULL, 'Weil er keine Zeit hat, kommt er nicht.', '["Weil er keine Zeit hat, kommt er nicht.","Weil er keine Zeit hat, kommt er nicht"]'::jsonb, 'In a weil clause, hat must move to the end of that clause.', 'Im weil-Satz muss hat ans Ende dieses Nebensatzes.', NULL, 24, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'weil + Subjekt + keine Zeit + hat.', 'weil + Subjekt + keine Zeit + hat.', 'Common Subordinate Clause Mistakes'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b2975b84-c98b-5383-b7d4-d26308058d07'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '7cd3bbcd-44bf-5732-b99a-df07d95c3935'::uuid, '0bec80db-6066-4d73-a4f1-29ef6c75c0d5'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Ich weiß nicht, ob kommt sie morgen."', 'Find the error and write the sentence correctly: "Ich weiß nicht, ob kommt sie morgen." (word order in an ob clause)', NULL, 'Ich weiß nicht, ob sie morgen kommt.', '["Ich weiß nicht, ob sie morgen kommt.","Ich weiß nicht, ob sie morgen kommt"]'::jsonb, 'In an ob clause, kommt must move to the end.', 'Im ob-Satz muss kommt ans Ende.', NULL, 25, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'ob + Subjekt + morgen + kommt.', 'ob + Subjekt + morgen + kommt.', 'Common Subordinate Clause Mistakes'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '7cd3bbcd-44bf-5732-b99a-df07d95c3935'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6f8cfe10-47d9-56ee-82cc-cb071b582669'::uuid, 'b11f911b-9c17-4100-b0a7-4a6c905773a4'::uuid, 4, 'fill_blank', 'Das ist ___ Restaurant am Bahnhof. (billig)', 'That is the cheapest restaurant near the station. Superlative before a neuter noun. Base form: billig.', NULL, 'das billigste', '["das billigste","das billigste."]'::jsonb, 'Before a noun: der/die/das + adjective + ste. Restaurant is neuter: das billigste.', 'Vor einem Nomen: der/die/das + Adjektiv + ste. Restaurant ist neutrum: das billigste.', NULL, 9, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'billig + ste, with the article das for the neuter noun Restaurant.', 'billig + ste, mit dem Artikel das für das neutrale Nomen Restaurant.', 'Superlative Before Nouns'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6f8cfe10-47d9-56ee-82cc-cb071b582669'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '103937d5-79dd-572c-828e-5fa62ea6db12'::uuid, 'b11f911b-9c17-4100-b0a7-4a6c905773a4'::uuid, 4, 'fill_blank', 'Sie ist ___ Schülerin in der Klasse. (gut)', 'She is the best student in the class. Irregular superlative before a feminine noun. Base form: gut.', NULL, 'die beste', '["die beste","die beste."]'::jsonb, 'gut is irregular: die beste, never die gutste.', 'gut ist unregelmäßig: die beste, nie die gutste.', NULL, 10, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'gut - besser - die beste is one of the big irregular chains.', 'gut - besser - die beste ist eine der unregelmäßigen Ketten.', 'Irregular Superlatives'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '103937d5-79dd-572c-828e-5fa62ea6db12'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3e418339-2e0f-5788-878e-d4f842f8e657'::uuid, 'b11f911b-9c17-4100-b0a7-4a6c905773a4'::uuid, 4, 'fill_blank', 'Ich fahre ___ mit dem Rad. (gern)', 'I like traveling by bike the most. Superlative adverb after the verb. Base form: gern.', NULL, 'am liebsten', '["am liebsten","am liebsten."]'::jsonb, 'gern is irregular: am liebsten, used as an adverb without a noun.', 'gern ist unregelmäßig: am liebsten, hier ohne Nomen.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'gern - lieber - am liebsten is one of the big irregular chains.', 'gern - lieber - am liebsten ist eine der unregelmäßigen Ketten.', 'Common Superlative Phrases'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3e418339-2e0f-5788-878e-d4f842f8e657'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'fa0126b3-9d66-5ade-b961-89c57cf7fc9c'::uuid, 'b11f911b-9c17-4100-b0a7-4a6c905773a4'::uuid, 4, 'fill_blank', 'Von allen Zimmern ist dieses ___. (hell, am-Form)', 'Of all the rooms, this one is the brightest (predicate superlative, am-form). Base form: hell.', NULL, 'am hellsten', '["am hellsten","am hellsten."]'::jsonb, 'hell is regular: no umlaut, no extra e, just add -sten.', 'hell ist regelmäßig: kein Umlaut, kein extra e, einfach -sten.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'hell ends in -l, so it takes the plain -sten ending: am hellsten.', 'hell endet auf -l: die einfache Endung -sten: am hellsten.', 'Forming am + sten'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'fa0126b3-9d66-5ade-b961-89c57cf7fc9c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0f891dbd-ce0a-55a6-97ba-5711fe41c373'::uuid, 'b11f911b-9c17-4100-b0a7-4a6c905773a4'::uuid, 5, 'fill_blank', 'Das war ___ Winter seit Jahren. (kalt)', 'That was the coldest winter in years. Superlative before a masculine noun, with umlaut. Base form: kalt.', NULL, 'der kälteste', '["der kälteste","der kälteste."]'::jsonb, 'kalt takes an umlaut and the -e-sten pattern: der kälteste.', 'kalt bekommt einen Umlaut und die Endung -este: der kälteste.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'kalt ends in t, so it adds -este, plus the umlaut: kälteste.', 'kalt endet auf t: -este, plus Umlaut: kälteste.', 'Superlative Endings in Every Case'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0f891dbd-ce0a-55a6-97ba-5711fe41c373'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '97d0e719-5f30-5811-924b-3cb7273fe88b'::uuid, 'b11f911b-9c17-4100-b0a7-4a6c905773a4'::uuid, 5, 'sentence_building', 'Schreib den Satz: [teuer (Superlativ, am-Form) / sein / Rucksack / dieser]', 'Write the sentence: This backpack is the most expensive (predicate superlative, am-form). Start with ''Dieser''.', NULL, 'Dieser Rucksack ist am teuersten.', '["Dieser Rucksack ist am teuersten.","Dieser Rucksack ist am teuersten"]'::jsonb, 'After sein without a noun, use am + sten: am teuersten.', 'Nach sein ohne Nomen: am + sten: am teuersten.', NULL, 14, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'teuer ends in -er, so the regular -sten ending applies: am teuersten.', 'teuer endet auf -er, reguläre Endung -sten: am teuersten.', 'Forming am + sten'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '97d0e719-5f30-5811-924b-3cb7273fe88b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '507a3097-f4d1-5379-aa08-6d75444854b1'::uuid, 'b11f911b-9c17-4100-b0a7-4a6c905773a4'::uuid, 5, 'sentence_building', 'Schreib den Satz: [gut (Superlativ, am-Form) / kochen / Oma / meine]', 'Write the sentence: My grandma cooks the best (predicate superlative, am-form). Start with ''Meine''.', NULL, 'Meine Oma kocht am besten.', '["Meine Oma kocht am besten.","Meine Oma kocht am besten"]'::jsonb, 'gut is irregular: am besten, not am gutsten.', 'gut ist unregelmäßig: am besten, nicht am gutsten.', NULL, 15, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'gut - besser - am besten is one of the big three irregulars.', 'gut - besser - am besten ist einer der drei Unregelmäßigen.', 'Irregular Superlatives'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '507a3097-f4d1-5379-aa08-6d75444854b1'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3cfecf75-7643-5ddf-9d58-d03dae1b7ff3'::uuid, 'b11f911b-9c17-4100-b0a7-4a6c905773a4'::uuid, 5, 'sentence_building', 'Schreib den Satz: [Kakao / gern / trinken / Kinder / viel (Superlativ)]', 'Write the sentence: Most children like drinking cocoa. Plural superlative of viel (die meisten). Start with ''Die''.', NULL, 'Die meisten Kinder trinken gern Kakao.', '["Die meisten Kinder trinken gern Kakao.","Die meisten Kinder trinken gern Kakao"]'::jsonb, 'die meisten is the plural superlative of viel, used before the plural noun Kinder.', 'die meisten ist der Plural-Superlativ von viel, vor dem Plural-Nomen Kinder.', NULL, 16, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'viel - mehr - die meisten, agreeing with the plural noun Kinder.', 'viel - mehr - die meisten, passend zum Plural-Nomen Kinder.', 'Irregular Superlatives'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3cfecf75-7643-5ddf-9d58-d03dae1b7ff3'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ea24da96-e054-534f-8d1a-708153deb0e6'::uuid, 'b11f911b-9c17-4100-b0a7-4a6c905773a4'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Das war der gutste Tag im Urlaub."', 'Find the error and write the sentence correctly: "Das war der gutste Tag im Urlaub." (irregular superlative)', NULL, 'Das war der beste Tag im Urlaub.', '["Das war der beste Tag im Urlaub.","Das war der beste Tag im Urlaub"]'::jsonb, 'gut is irregular: der beste, never der gutste.', 'gut ist unregelmäßig: der beste, nie der gutste.', NULL, 17, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'gut - besser - der beste is one of the big irregular chains.', 'gut - besser - der beste ist eine der unregelmäßigen Ketten.', 'Mistakes with the Superlative'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ea24da96-e054-534f-8d1a-708153deb0e6'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b661f427-2340-5be3-a0a6-3bd6eddcd215'::uuid, 'b11f911b-9c17-4100-b0a7-4a6c905773a4'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Sie läuft am schnellste von allen."', 'Find the error and write the sentence correctly: "Sie läuft am schnellste von allen." (missing final -n)', NULL, 'Sie läuft am schnellsten von allen.', '["Sie läuft am schnellsten von allen.","Sie läuft am schnellsten von allen"]'::jsonb, 'am + sten always ends in -n: am schnellsten, not am schnellste.', 'am + sten endet immer auf -n: am schnellsten, nicht am schnellste.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The am-form always keeps the final -n: am schnellsten.', 'Die am-Form behält immer das -n: am schnellsten.', 'Mistakes with the Superlative'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b661f427-2340-5be3-a0a6-3bd6eddcd215'::uuid);


